window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"module":"yiliao","prompt":"黄曲霉毒素主要诱发？","options":["肝细胞癌","胃癌","肺癌","皮肤癌"],"answer":0,"explanation":"黄曲霉毒素B1是强致肝癌物，霉变花生粮食中多见。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1501","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肿瘤组织生长速度的标志之一是？","options":["间质多少","肿瘤颜色","肿瘤质地","核分裂象多少"],"answer":3,"explanation":"核分裂象多提示生长活跃，恶性可能大。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1502","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"恶性肿瘤血道转移时，瘤栓经椎静脉系统最易转移到？","options":["肺","椎骨和脑","肝","肾"],"answer":1,"explanation":"椎静脉丛无瓣膜，压力变化时瘤栓逆流至椎骨、脑。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1503","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肿瘤免疫组化中，上皮源性肿瘤标志物是？","options":["角蛋白（CK）","结蛋白","波形蛋白","S-100"],"answer":0,"explanation":"CK阳性提示上皮来源；结蛋白为肌源性，S-100为神经源性。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1504","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肉瘤的肉眼特点是？","options":["黑褐色","灰白、质硬、干燥","囊性水样","鱼肉状、灰红色、质软细腻"],"answer":3,"explanation":"肉瘤切面灰红鱼肉状，质软，常伴出血坏死。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1505","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"癌肉瘤是指？","options":["只有肉瘤成分","只有癌成分","肿瘤内既有癌又有肉瘤成分","良性混合瘤"],"answer":2,"explanation":"同一肿瘤中含癌和肉瘤两种成分称癌肉瘤。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1506","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肿瘤分期的主要依据不包括？","options":["远处转移情况","原发肿瘤大小和浸润深度","淋巴结转移情况","肿瘤的异型性大小"],"answer":3,"explanation":"TNM分期依据肿瘤大小/深度、淋巴结、远处转移；异型性属分级依据。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1507","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"动脉粥样硬化病变主要累及？","options":["大、中动脉内膜","小动脉全层","毛细血管","静脉"],"answer":0,"explanation":"AS主要发生于大中动脉（主动脉、冠脉、脑动脉等）内膜。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1508","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"动脉粥样硬化斑块中吞噬脂质的泡沫细胞来源于？","options":["成纤维细胞","内皮细胞","淋巴细胞","巨噬细胞和平滑肌细胞"],"answer":3,"explanation":"氧化LDL被巨噬细胞和平滑肌细胞吞噬形成泡沫细胞。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1509","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"动脉粥样硬化的继发改变不包括？","options":["斑块破裂形成溃疡","斑块内出血","管腔扩大","血栓形成"],"answer":2,"explanation":"AS斑块使管腔狭窄而非扩大；可继发出血、溃疡、血栓、钙化。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1510","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"冠状动脉粥样硬化最常累及的血管是？","options":["左冠状动脉回旋支","右冠状动脉","左冠状动脉前降支","左冠状动脉主干"],"answer":2,"explanation":"前降支最常受累，其次右冠、左旋支。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1511","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心肌梗死最常发生的部位是？","options":["室间隔后部","右心室","左心房","左心室前壁及心尖部"],"answer":3,"explanation":"前降支供血区（左室前壁、心尖、室间隔前部）最常梗死。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1512","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心肌梗死后血清心肌标志物最早升高的是？","options":["天冬氨酸转氨酶","肌酸激酶同工酶（CK-MB）","肌钙蛋白","乳酸脱氢酶"],"answer":2,"explanation":"肌钙蛋白（cTnI/cTnT）特异性高、出现早，是首选标志物。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1513","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"良性高血压的基本病变是？","options":["细小动脉玻璃样变","细小动脉纤维素样坏死","大动脉粥样硬化","血管炎"],"answer":0,"explanation":"良性高血压以细小动脉玻璃样变（透明变性）为特征。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1514","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"恶性高血压的特征性病变是？","options":["动脉粥样斑块","动脉玻璃样变","细小动脉纤维素样坏死（坏死性细动脉炎）","动脉瘤"],"answer":2,"explanation":"恶性高血压以增生性小动脉硬化和纤维素样坏死为特征。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1515","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压性心脏病的主要改变是？","options":["左心室向心性肥大","右心室肥大","左心室扩张为主","心腔缩小"],"answer":0,"explanation":"外周阻力增高致左室代偿性肥厚，称向心性肥大。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1516","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压脑出血最常见的部位是？","options":["基底节（内囊附近）","小脑","脑桥","额叶"],"answer":0,"explanation":"豆纹动脉从大脑中动脉直角分出，基底节区最易出血。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1517","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"风湿病的基本病变分为三期，其顺序是？","options":["瘢痕期、增生期、渗出期","增生期、变质期、瘢痕期","变质渗出期、增生期（肉芽肿期）、瘢痕期","渗出期、瘢痕期、增生期"],"answer":2,"explanation":"风湿病经历变质渗出、肉芽肿增生、纤维化瘢痕三期。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1518","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"风湿病具有诊断意义的病变是？","options":["上皮样肉芽肿","R-S细胞","泡沫细胞","Aschoff小体（风湿小体）"],"answer":3,"explanation":"Aschoff小体是风湿病特征性肉芽肿。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1519","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"风湿性心内膜炎最常累及的瓣膜是？","options":["主动脉瓣","三尖瓣","二尖瓣","肺动脉瓣"],"answer":2,"explanation":"二尖瓣最常受累，其次二尖瓣+主动脉瓣联合受累。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1520","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"风湿性心内膜炎瓣膜上形成的赘生物特点是？","options":["小、灰白、不易脱落（白色血栓）","大、松脆、易脱落","化脓性","含大量细菌"],"answer":0,"explanation":"疣状赘生物为血小板纤维蛋白构成，机化后致瓣膜变形。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1521","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"亚急性感染性心内膜炎最常见的病原体是？","options":["结核分枝杆菌","金黄色葡萄球菌","大肠埃希菌","草绿色链球菌"],"answer":3,"explanation":"亚急性者以草绿色链球菌多见；急性者以金黄色葡萄球菌多见。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1522","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"二尖瓣狭窄时心脏的典型改变是？","options":["左室肥大、靴形心","左房扩大、梨形心","全心扩大","心包积液"],"answer":1,"explanation":"二尖瓣狭窄致左房淤血扩大，肺动脉高压右室肥大，呈梨形心。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1523","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"主动脉瓣关闭不全的心脏改变是？","options":["右室肥大","左房扩大","左心室扩大（靴形心）","心腔缩小"],"answer":2,"explanation":"主动脉瓣关闭不全致舒张期血液反流，左室容量负荷增大而扩大。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1524","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"动脉粥样硬化的主要危险因素不包括？","options":["高脂血症","高密度脂蛋白增高","高血压","吸烟"],"answer":1,"explanation":"HDL有抗AS作用，HDL降低才是危险因素。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1525","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性支气管炎的主要诊断依据是？","options":["肺部啰音","咳嗽咳痰每年至少3个月、连续2年以上","胸片示肺纹理增粗","痰培养阳性"],"answer":1,"explanation":"临床诊断标准：咳、痰或喘每年≥3月，连续≥2年。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1526","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性支气管炎最常见的并发症是？","options":["肺癌","肺脓肿","支气管扩张","肺气肿"],"answer":3,"explanation":"慢支反复发作致细支气管狭窄阻塞，形成阻塞性肺气肿。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1527","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阻塞性肺气肿的病理特征是？","options":["肺组织实变","肺泡间隔增厚","支气管壁钙化","终末细支气管以远的肺组织过度充气、膨胀、弹性减退"],"answer":3,"explanation":"肺气肿为呼吸性细支气管及肺泡的持久性扩张含气。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1528","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"大叶性肺炎的病原体主要是？","options":["肺炎链球菌","金黄色葡萄球菌","肺炎克雷伯菌","结核分枝杆菌"],"answer":0,"explanation":"大叶性肺炎90%以上由肺炎链球菌引起。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1529","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"大叶性肺炎灰色肝样变期肺泡腔内充满？","options":["大量纤维素和中性粒细胞","大量浆液","红细胞为主","肉芽组织"],"answer":0,"explanation":"灰色肝样变期肺泡腔大量纤维素和中性粒细胞，肺实变灰白。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1530","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"大叶性肺炎的并发症不包括？","options":["肺肉质变","肺脓肿（少见但可发生）","感染性休克","支气管扩张（少见）"],"answer":1,"explanation":"大叶性肺炎并发症：肉质变、肺脓肿脓胸、休克等；支气管扩张非典型并发症。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1531","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺肉质变（机化性肺炎）的发生机制是？","options":["纤维素渗出过多","中性粒细胞渗出过少，纤维素不能完全溶解吸收","细菌毒力强","肺泡壁破坏"],"answer":1,"explanation":"中性粒细胞释放的蛋白酶不足，纤维素被肉芽组织机化。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1532","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"小叶性肺炎的病变特点是？","options":["以细支气管为中心的化脓性炎","肺泡纤维素性炎","间质性肺炎","干酪性肺炎"],"answer":0,"explanation":"小叶性肺炎（支气管肺炎）以细支气管为中心、累及周围肺泡。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1533","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"小叶性肺炎的好发人群是？","options":["青壮年","小儿、老人及体弱者","运动员","孕妇"],"answer":1,"explanation":"小叶性肺炎常为其他疾病的并发症，好发于小儿老人。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1534","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒性肺炎的病变特点是？","options":["肺泡腔大量中性粒细胞","肺间质淋巴细胞单核细胞浸润","肺泡纤维素性炎","化脓性支气管炎"],"answer":1,"explanation":"病毒性肺炎为间质性肺炎，肺泡间隔增宽、炎细胞浸润。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1535","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺癌最常见的组织学类型是？","options":["大细胞癌","小细胞癌","腺癌（近年上升）或鳞癌","腺鳞癌"],"answer":2,"explanation":"鳞癌曾最常见，现腺癌在许多地区已居首位；小细胞癌恶性度最高。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1536","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中央型肺癌多起源于？","options":["肺泡上皮","段以下支气管","细支气管","主支气管和叶支气管"],"answer":3,"explanation":"中央型肺癌发生于段及以上大支气管，鳞癌多见。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1537","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"与职业暴露相关的肺尘埃沉着症（硅肺）的基本病变是？","options":["支气管扩张","肺泡蛋白沉积","硅结节形成和肺纤维化","肺肉质变"],"answer":2,"explanation":"SiO₂粉尘致硅结节和弥漫纤维化。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1538","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"鼻咽癌在我国的高发地区是？","options":["东北地区","广东、广西等南方省份","西北地区","华北平原"],"answer":1,"explanation":"鼻咽癌两广等地高发，与EB病毒感染相关。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1539","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺源性心脏病最常见的原因是？","options":["肺癌","肺结核","支气管哮喘","慢性阻塞性肺疾病"],"answer":3,"explanation":"COPD致肺动脉高压，是慢性肺心病最常见原因。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1540","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性胃炎最常见的病因是？","options":["幽门螺杆菌感染","长期饮酒","胆汁反流","自身免疫"],"answer":0,"explanation":"Hp感染是慢性活动性胃炎的主要病因。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1541","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胃溃疡的好发部位是？","options":["胃底","胃大弯","胃小弯近幽门部（胃窦部）","贲门部"],"answer":2,"explanation":"胃溃疡多位于胃小弯近幽门处。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1542","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"十二指肠溃疡的好发部位是？","options":["升部","降部","水平部","十二指肠球部前壁"],"answer":3,"explanation":"球部前壁最常见。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1543","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"消化性溃疡的并发症不包括？","options":["幽门梗阻","出血","穿孔","癌变（十二指肠溃疡几乎不癌变）"],"answer":3,"explanation":"胃溃疡可癌变（约1%），十二指肠溃疡一般不癌变。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1544","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胃溃疡底部由表及里的分层是？","options":["肉芽层、坏死层、渗出层、瘢痕层","坏死层、渗出层、瘢痕层、肉芽层","渗出层、坏死层、肉芽组织层、瘢痕层","瘢痕层、肉芽层、坏死层、渗出层"],"answer":2,"explanation":"溃疡四层：炎性渗出、坏死、肉芽组织、瘢痕。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1545","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒性肝炎的基本病变不包括？","options":["肝细胞变性（气球样变）","假小叶形成","肝细胞坏死","炎细胞浸润"],"answer":1,"explanation":"假小叶是肝硬化的特征，不是肝炎基本病变。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1546","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性普通型肝炎的主要病变是？","options":["大片坏死","肝细胞广泛变性、点状坏死","桥接坏死","假小叶形成"],"answer":1,"explanation":"急性普通型肝炎以细胞水肿（气球样变）和点状坏死为主。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1547","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性肝炎肝细胞碎片状坏死是指？","options":["肝小叶周边界板肝细胞的灶状坏死崩解","肝小叶中央坏死","大片坏死","点状坏死"],"answer":0,"explanation":"碎片状坏死位于汇管区周围、破坏界板，是慢性肝炎特征。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1548","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性重型肝炎的病变特点是？","options":["肝细胞水肿为主","肝细胞大片坏死、肝体积明显缩小","假小叶形成","肝细胞脂肪变"],"answer":1,"explanation":"急性重型（暴发性）肝炎肝细胞大块坏死，肝脏急性缩小，死亡率高。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1549","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"毛玻璃样肝细胞见于？","options":["酒精性肝病","乙型肝炎病毒携带者（HBsAg大量沉积）","药物性肝损伤","自身免疫性肝炎"],"answer":1,"explanation":"HBsAg在内质网聚集，胞质呈毛玻璃样。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1550","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝硬化的特征性病理改变是？","options":["点状坏死","肝细胞水肿","假小叶形成","毛玻璃样变"],"answer":2,"explanation":"纤维间隔分割肝小叶形成假小叶，是肝硬化确诊依据。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1551","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"门脉高压的表现不包括？","options":["脾肿大","肝掌和蜘蛛痣（雌激素灭活减少所致，属肝功能不全）","腹水","侧支循环形成"],"answer":1,"explanation":"肝掌、蜘蛛痣为肝功能障碍（雌激素灭活下降）表现，非门脉高压直接表现。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1552","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"门脉高压时侧支循环形成，最危险的是？","options":["食管下段-胃底静脉丛曲张破裂出血","脐周静脉曲张","痔静脉曲张","腹膜后静脉曲张"],"answer":0,"explanation":"食管胃底静脉破裂致上消化道大出血，是主要死因。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1553","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性阑尾炎的主要病变类型是？","options":["纤维素性炎","化脓性炎","肉芽肿性炎","浆液性炎"],"answer":1,"explanation":"急性阑尾炎多为急性化脓性炎。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1554","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"大肠癌最好发的部位是？","options":["直肠和乙状结肠","升结肠","横结肠","阑尾"],"answer":0,"explanation":"直肠最多见，其次乙状结肠。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1555","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"原发性肝癌最常见的类型是？","options":["混合细胞型","胆管细胞癌","肝细胞癌","转移性肝癌"],"answer":2,"explanation":"肝细胞癌占原发性肝癌的90%以上。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1556","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性胰腺炎的主要发病机制是？","options":["胰管结石机械损伤","细菌直接感染","免疫复合物沉积","胰酶被激活后自身消化"],"answer":3,"explanation":"胆汁反流等使胰酶在胰内激活，消化自身组织。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1557","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"食管癌最常见的组织学类型是？","options":["黏液癌","腺癌","小细胞癌","鳞状细胞癌"],"answer":3,"explanation":"我国食管癌90%以上为鳞癌，与饮食因素相关。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1558","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"霍奇金淋巴瘤的典型发病年龄呈？","options":["单峰（仅青年）","双峰（青年和老年）","单峰（仅老年）","均匀分布"],"answer":1,"explanation":"霍奇金淋巴瘤发病呈青年和老年双峰。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1559","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"霍奇金淋巴瘤最常累及的部位是？","options":["颈部和锁骨上淋巴结","脾","骨髓","肝脏"],"answer":0,"explanation":"典型表现为颈部无痛性淋巴结肿大，连续性蔓延。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1560","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"非霍奇金淋巴瘤的扩散特点是？","options":["跳跃式扩散，可累及结外器官","沿淋巴管连续蔓延","只累及淋巴结","不累及骨髓"],"answer":0,"explanation":"NHL呈跳跃性，结外侵犯和骨髓受累常见。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1561","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性白血病的骨髓象特征是？","options":["骨髓纤维化","成熟细胞增多","原始细胞显著增生（≥20%）","脂肪组织增多"],"answer":2,"explanation":"急性白血病骨髓中原始细胞≥20%（WHO标准）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1562","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性粒细胞白血病的特征性标志是？","options":["免疫球蛋白重排","R-S细胞","Auer小体","Ph染色体（BCR-ABL融合基因）"],"answer":3,"explanation":"CML特征性Ph染色体t(9;22)，靶向药伊马替尼有效。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1563","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"类白血病反应与白血病的主要鉴别点是？","options":["血小板减少","白细胞数量","贫血程度","病因去除后血象可恢复、NAP积分增高"],"answer":3,"explanation":"类白血病反应有明确病因，NAP积分升高，原发病好转后恢复。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1564","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"淋巴结反应性增生与淋巴瘤的鉴别要点是？","options":["淋巴结大小","淋巴结结构是否保留","有无疼痛","发病年龄"],"answer":1,"explanation":"反应性增生保留淋巴结正常结构；淋巴瘤结构破坏。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1565","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"AIDS患者最常并发的肿瘤是？","options":["卡波西肉瘤","霍奇金淋巴瘤","肺癌","皮肤鳞癌"],"answer":0,"explanation":"HIV感染者卡波西肉瘤（HHV-8相关）最常见。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1566","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肾小球肾炎的发病机制主要是？","options":["结石刺激","细菌直接感染","免疫介导的炎症反应（免疫复合物等）","缺血"],"answer":2,"explanation":"肾炎由免疫复合物或抗基底膜抗体介导。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1567","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性弥漫增生性肾小球肾炎（毛细血管内增生性）的病原主要是？","options":["A组乙型溶血性链球菌","金黄色葡萄球菌","大肠埃希菌","结核分枝杆菌"],"answer":0,"explanation":"链球菌感染后肾炎多见于儿童，表现为急性肾炎综合征。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1568","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性肾炎综合征的表现不包括？","options":["高血压","血尿","水肿","大量蛋白尿（>3.5g/d）"],"answer":3,"explanation":"大量蛋白尿、低蛋白血症属肾病综合征；肾炎综合征为血尿、蛋白尿、水肿、高血压。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1569","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"快速进行性（急进性）肾小球肾炎的特征性病变是？","options":["肾小球壁层上皮细胞增生形成新月体","内皮细胞增生","系膜细胞增生","肾小管坏死"],"answer":0,"explanation":"新月体性肾炎病情急进，预后差。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1570","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肾病综合征的表现不包括？","options":["大量蛋白尿","血尿为主","低白蛋白血症","明显水肿"],"answer":1,"explanation":"肾病综合征四联征：大量蛋白尿、低蛋白、水肿、高脂血症。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1571","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"儿童肾病综合征最常见的病理类型是？","options":["膜性肾病","微小病变性肾小球病","系膜增生性肾炎","新月体性肾炎"],"answer":1,"explanation":"微小病变好发于儿童，激素治疗效果好。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1572","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"成人肾病综合征最常见的病理类型是？","options":["膜性肾病","微小病变","局灶节段性硬化","系膜毛细血管性肾炎"],"answer":0,"explanation":"膜性肾病多见于中老年，为成人肾病综合征最常见类型。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1573","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"膜性肾病的免疫病理特点是？","options":["无沉积","线性沉积","IgG和C3沿毛细血管壁颗粒状沉积","系膜区沉积"],"answer":2,"explanation":"膜性肾病为原位免疫复合物，颗粒状沉积于上皮下。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1574","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性肾盂肾炎的病变特点是？","options":["肾小球新月体","肾盂肾盏变形、间质纤维化和慢性炎细胞浸润","系膜增生","肾小球玻璃样变为主"],"answer":1,"explanation":"肾盂肾炎为细菌感染引起的间质性化脓性炎。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1575","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性肾盂肾炎的感染途径主要是？","options":["直接蔓延","血源性感染","淋巴道感染","上行性感染"],"answer":3,"explanation":"上行性感染（尿道→膀胱→输尿管→肾）最常见，女性多见。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1576","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肾细胞癌的典型三联征是？","options":["血尿、腰痛、腹部肿块","水肿、蛋白尿、高血压","发热、盗汗、消瘦","尿频、尿急、尿痛"],"answer":0,"explanation":"肾癌三联征：无痛性血尿、肾区疼痛、肿块。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1577","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"膀胱移行细胞癌最常见的临床表现是？","options":["无痛性肉眼血尿","膀胱刺激征","排尿困难","脓尿"],"answer":0,"explanation":"膀胱癌首发症状多为间歇性无痛性血尿。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1578","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"子宫颈癌前病变（CIN）的分级依据是？","options":["有无坏死","细胞大小","异型细胞累及上皮的范围（1/3、2/3、全层）","间质浸润"],"answer":2,"explanation":"CINⅠ~Ⅲ级按异型细胞占上皮层比例分级。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1579","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乳腺癌最常见的组织学类型是？","options":["黏液癌","浸润性小叶癌","髓样癌","浸润性导管癌"],"answer":3,"explanation":"浸润性导管癌占乳腺癌的70%~80%。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1580","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乳腺癌累及淋巴管致皮肤水肿，出现？","options":["酒窝征","橘皮样外观","溃疡","乳头溢液"],"answer":1,"explanation":"癌细胞堵塞真皮淋巴管，皮肤水肿、毛囊下陷呈橘皮样。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1581","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乳腺癌侵犯悬韧带（Cooper韧带）可出现？","options":["皮肤溃疡","橘皮样变","乳头凹陷和酒窝征","乳头湿疹"],"answer":2,"explanation":"韧带受牵拉使皮肤凹陷（酒窝征）、乳头回缩。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1582","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"葡萄胎的病变特点是？","options":["绒毛血管丰富","绒毛水肿、滋养层细胞增生、无胎儿（完全性）","胎儿发育正常","间质纤维化"],"answer":1,"explanation":"完全性葡萄胎绒毛普遍水肿呈葡萄串状，滋养细胞增生。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1583","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"侵蚀性葡萄胎与绒毛膜癌的主要区别是？","options":["有无绒毛结构","有无出血","滋养细胞多少","hCG水平"],"answer":0,"explanation":"侵蚀性葡萄胎可见绒毛；绒癌无绒毛、无间质血管。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1584","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"绒毛膜癌最常见的转移部位是？","options":["肺","脑","肝","阴道"],"answer":0,"explanation":"绒癌经血道转移，肺转移最常见。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1585","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"前列腺增生主要发生于？","options":["中央区","外周区","前列腺移行区（尿道周围）","精囊"],"answer":2,"explanation":"良性前列腺增生起自移行区；前列腺癌多发生于外周区。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1586","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"前列腺癌的实验室标志物是？","options":["CA125","癌胚抗原","甲胎蛋白","前列腺特异性抗原（PSA）"],"answer":3,"explanation":"PSA升高提示前列腺癌，用于筛查和监测。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1587","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"弥漫性毒性甲状腺肿（Graves病）的病变特点是？","options":["滤泡萎缩","滤泡上皮增生、胶质稀薄、边缘吸收空泡","胶质增多","纤维化"],"answer":1,"explanation":"甲亢时滤泡上皮增生呈柱状，胶质吸收形成空泡。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1588","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲状腺癌中最常见的类型是？","options":["滤泡癌","乳头状癌","髓样癌","未分化癌"],"answer":1,"explanation":"乳头状癌占60%以上，生长慢、预后最好，易淋巴转移。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1589","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲状腺乳头状癌的特征性形态是？","options":["Auer小体","R-S细胞","砂粒体和毛玻璃样核","朗汉斯巨细胞"],"answer":2,"explanation":"核呈毛玻璃样、可见砂粒体，为乳头状癌特征。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1590","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病的主要代谢紊乱是？","options":["仅脂肪代谢紊乱","仅糖代谢紊乱","糖、脂肪、蛋白质代谢紊乱","水盐代谢单一紊乱"],"answer":2,"explanation":"胰岛素不足引起糖脂蛋白代谢全面紊乱。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1591","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"1型糖尿病的病变特点是？","options":["胰岛淀粉样变","胰岛纤维化为主","B细胞正常","胰岛B细胞明显减少、淋巴细胞浸润"],"answer":3,"explanation":"1型糖尿病自身免疫破坏B细胞；2型晚期见胰岛淀粉样变。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1592","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"2型糖尿病的病理特征是？","options":["B细胞完全缺失","胰岛淀粉样变性、B细胞数量轻度减少","胰岛脓肿","胰岛钙化"],"answer":1,"explanation":"2型糖尿病胰岛可见淀粉样物质沉积。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1593","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流行性乙型脑炎的病变特点是？","options":["肉芽肿性炎","化脓性脑膜炎","神经细胞变性坏死、筛网状软化灶、血管套、胶质结节","脱髓鞘"],"answer":2,"explanation":"乙脑为病毒性脑实质炎，四大病变：神经细胞坏死、软化灶、血管套、胶质结节。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1594","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流行性脑脊髓膜炎的病变特点是？","options":["脱髓鞘","脑实质软化灶","肉芽肿","蛛网膜下腔大量中性粒细胞渗出（化脓性脑膜炎）"],"answer":3,"explanation":"流脑由脑膜炎奈瑟菌引起，为化脓性脑膜炎症。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1595","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流脑与乙脑的主要区别是？","options":["流脑累及脑膜，乙脑累及脑实质","病原体相同","发病季节相同","预后相同"],"answer":0,"explanation":"流脑为脑膜炎病变，乙脑为脑实质炎症。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1596","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"颅内最常见的原发性肿瘤是？","options":["脑膜瘤","胶质瘤","垂体瘤","神经鞘瘤"],"answer":1,"explanation":"胶质瘤占颅内原发肿瘤的40%以上。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1597","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脑出血最常见的部位是？","options":["额叶","小脑","脑桥","基底节区"],"answer":3,"explanation":"高血压脑出血好发基底节（豆纹动脉）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1598","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脑积水是指？","options":["脑萎缩","脑组织水肿","颅内积气","脑脊液过多积聚于脑室系统"],"answer":3,"explanation":"脑脊液生成增多或循环吸收障碍致脑室扩大。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1599","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核病的基本病变不包括？","options":["增生性病变（结核结节）","渗出性病变","化脓性炎","变质性病变（干酪样坏死）"],"answer":2,"explanation":"结核基本病变为渗出、增生、坏死（变质）三种，非化脓性。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1600","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物从给药部位吸收入血后，首次经肠道和肝脏被代谢减少的现象称为？","options":["肝肠循环","首过消除","生物转化","酶诱导"],"answer":1,"explanation":"口服药物经胃肠吸收后经门静脉入肝，部分被代谢灭活，称首过消除，故口服生物利用度降低。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1601","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物半衰期（t1/2）是指？","options":["药物作用最强的时间","药物被完全清除所需的时间","药物起效所需的时间","血浆药物浓度下降一半所需的时间"],"answer":3,"explanation":"半衰期反映药物消除速度，是确定给药间隔的重要依据。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1602","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"一级动力学消除的特点是？","options":["单位时间内按恒定量消除","单位时间内按恒定比例消除","消除速度与剂量无关","半衰期随剂量增大而延长"],"answer":1,"explanation":"一级动力学消除中，单位时间消除恒定比例的药物，半衰期恒定。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1603","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物的不良反应是指？","options":["正常剂量下出现的与用药目的无关的作用","用药剂量过大引起的毒性反应","药物引起的过敏反应","药物依赖引起的戒断症状"],"answer":0,"explanation":"不良反应是治疗剂量下固有的作用，毒性反应、过敏反应等属于其他类型药源性疾病。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1604","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物的治疗指数是指？","options":["ED50/LD50的比值","LD50/ED50的比值","LD50×ED50","最大治疗量与最小治疗量之差"],"answer":1,"explanation":"治疗指数=LD50/ED50，比值越大说明药物越安全。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1605","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝药酶诱导剂的作用是？","options":["使肝药酶活性减弱，药物代谢减慢","使肝药酶活性增强，加速自身及其他药物代谢","直接灭活药物","增加药物吸收"],"answer":1,"explanation":"苯巴比妥、苯妥英钠等为肝药酶诱导剂，可加速药物代谢，使药效减弱。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1606","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"受体拮抗药的特点是？","options":["既有亲和力又有内在活性","与受体亲和力弱而内在活性强","与受体亲和力强而无内在活性","只增强受体数量"],"answer":2,"explanation":"拮抗药能占据受体但不激活受体，表现为阻断作用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1607","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物副作用的基本特点是？","options":["治疗剂量下发生、药物固有作用","剂量过大才发生","与体质异常有关","停药后必然加重"],"answer":0,"explanation":"副作用是治疗剂量下伴随治疗作用出现的固有反应，多数可预知。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1608","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"生物利用度是指？","options":["药物与血浆蛋白结合的比例","药物在肝脏代谢的比例","药物吸收进入体循环的相对量和速度","药物经肾排出的比例"],"answer":2,"explanation":"生物利用度反映制剂被吸收进入体循环的程度与速度。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1609","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"某药按一级动力学消除，其半衰期为4小时，单次给药后约经多少时间基本消除干净（约5个半衰期）？","options":["20小时","4小时","8小时","40小时"],"answer":0,"explanation":"约经5个半衰期（4×5=20小时）药物基本消除完毕。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1610","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"两种药物合用后作用增强称为？","options":["协同作用","拮抗作用","耐受性","依赖性"],"answer":0,"explanation":"协同作用指合用后药效增强；拮抗作用指药效减弱。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1611","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"反复用药后机体对药物的反应性降低，需增大剂量才能维持疗效，称为？","options":["耐受性","耐药性","依赖性","成瘾性"],"answer":0,"explanation":"耐受性指机体对药物反应性降低；耐药性指病原体或肿瘤细胞对药物敏感性降低。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1612","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物与血浆蛋白结合后，其特点是？","options":["排泄加快","药理活性增强","代谢加快","暂时失去药理活性"],"answer":3,"explanation":"结合型药物暂时无活性、不能跨膜转运和排泄，与游离型处于动态平衡。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1613","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"影响药物分布的主要因素不包括？","options":["局部器官血流量","药物与血浆蛋白结合率","体液pH值","药物的给药途径名称"],"answer":3,"explanation":"给药途径主要影响吸收，分布受蛋白结合率、pH、血流量、屏障等因素影响。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1614","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"弱酸性药物在碱性尿液中？","options":["吸收增加","排泄减慢","排泄加快","代谢停止"],"answer":2,"explanation":"弱酸性药物在碱性环境中解离增多，重吸收减少，排泄加快（如碱化尿液促巴比妥类排泄）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1615","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"毛果芸香碱对眼睛的作用是？","options":["缩瞳、降低眼内压","扩瞳、升高眼内压","缩瞳、升高眼内压","扩瞳、降低眼内压"],"answer":0,"explanation":"毛果芸香碱激动M受体，使瞳孔括约肌收缩（缩瞳）、房水回流通畅而降低眼内压，用于青光眼。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1616","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿托品对眼睛的作用是？","options":["扩瞳、升高眼内压、调节麻痹","缩瞳、降低眼内压","扩瞳、降低眼内压","缩瞳、调节痉挛"],"answer":0,"explanation":"阿托品阻断M受体，使瞳孔开大肌占优势而扩瞳、房水回流受阻致眼内压升高，禁用于青光眼。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1617","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿托品禁用于下列哪种疾病？","options":["内脏绞痛","心动过缓","有机磷中毒","青光眼"],"answer":3,"explanation":"阿托品升高眼内压，青光眼患者禁用。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1618","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿托品抢救有机磷中毒时，过量中毒的特效解救药是？","options":["毛果芸香碱（毒扁豆碱）","纳洛酮","新斯的明","阿托品本身"],"answer":0,"explanation":"阿托品中毒用M受体激动药毛果芸香碱（或毒扁豆碱）对抗，禁用新斯的明透过血脑屏障差。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1619","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"新斯的明治疗重症肌无力的机制是？","options":["抑制胆碱酯酶，使乙酰胆碱增多","激动骨骼肌N2受体","促进乙酰胆碱合成","阻断胆碱受体"],"answer":0,"explanation":"新斯的明抑制胆碱酯酶，使神经肌肉接头处乙酰胆碱蓄积，改善肌无力症状。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1620","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"新斯的明禁用于？","options":["重症肌无力","支气管哮喘和机械性肠梗阻","术后腹胀气","尿潴留"],"answer":1,"explanation":"新斯的明兴奋平滑肌，可加重哮喘和机械性肠梗阻病情，故禁用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1621","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"治疗有机磷农药中毒，阿托品化的指征不包括？","options":["肺部啰音减少","颜面潮红、皮肤干燥","瞳孔较前扩大","瞳孔缩小如针尖"],"answer":2,"explanation":"阿托品化表现为瞳孔扩大、颜面潮红、皮肤干燥、肺部啰音减少；瞳孔缩小是中毒表现。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1622","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肾上腺素抢救过敏性休克的机制不包括？","options":["抑制过敏介质释放","激动β受体兴奋心脏、扩张支气管","激动α受体升高血压","直接中和过敏原"],"answer":2,"explanation":"肾上腺素通过激动α、β受体收缩血管、兴奋心脏、扩张支气管并减少介质释放，不能中和过敏原。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1623","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素引起的过敏性休克首选急救药是？","options":["糖皮质激素","肾上腺素","抗组胺药","去甲肾上腺素"],"answer":1,"explanation":"肾上腺素是过敏性休克的首选急救药，能迅速缓解喉头水肿和支气管痉挛、升高血压。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1624","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"异丙肾上腺素的主要作用是？","options":["主要激动α受体","兴奋β受体，兴奋心脏、扩张支气管","主要阻断β受体","收缩皮肤黏膜血管"],"answer":1,"explanation":"异丙肾上腺素对β1、β2受体均有强大激动作用，用于心搏骤停、房室传导阻滞和支气管哮喘。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1625","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"去甲肾上腺素静脉滴注外漏易引起？","options":["支气管痉挛","心律失常","局部组织缺血坏死","低血压休克"],"answer":2,"explanation":"去甲肾上腺素强烈收缩血管，外漏可致局部组织缺血坏死，需及时用酚妥拉明局部拮抗。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1626","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"酚妥拉明属于？","options":["胆碱酯酶抑制药","β受体阻断药","α受体激动药","α受体阻断药"],"answer":3,"explanation":"酚妥拉明为短效α受体阻断药，用于外周血管痉挛性疾病和去甲肾上腺素外漏的解救。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1627","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"普萘洛尔禁用于？","options":["心绞痛","高血压","支气管哮喘","快速型心律失常"],"answer":2,"explanation":"普萘洛尔阻断支气管β2受体，可诱发或加重哮喘，支气管哮喘患者禁用。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1628","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"琥珀胆碱的作用特点是？","options":["非去极化型肌松药","去极化型肌松药，起效快、作用短暂","中枢性肌松药","胆碱酯酶抑制药"],"answer":1,"explanation":"琥珀胆碱为去极化型骨骼肌松弛药，静注后起效快，用于气管插管等短时操作。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1629","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"筒箭毒碱中毒的解救药是？","options":["纳洛酮","阿托品","毛果芸香碱","新斯的明"],"answer":3,"explanation":"筒箭毒碱为非去极化型肌松药，新斯的明抑制胆碱酯酶可对抗其作用。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1630","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"地西泮的主要药理作用不包括？","options":["镇痛","镇静催眠","抗惊厥","抗焦虑"],"answer":3,"explanation":"地西泮具有抗焦虑、镇静催眠、抗惊厥抗癫痫和中枢性肌松作用，无镇痛作用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1631","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"癫痫持续状态的首选药物是？","options":["卡马西平口服","苯妥英钠口服","地西泮静脉注射","乙琥胺口服"],"answer":2,"explanation":"地西泮静注是癫痫持续状态的首选，起效快、作用可靠。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1632","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"苯妥英钠是下列哪种癫痫发作的首选药？","options":["失神小发作","大发作（强直阵挛性发作）和部分性发作","肌阵挛发作","婴儿痉挛症"],"answer":1,"explanation":"苯妥英钠是癫痫大发作和部分性发作首选；对小发作（失神）无效甚至加重。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1633","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"治疗癫痫小发作（失神发作）的首选药是？","options":["苯巴比妥","苯妥英钠","乙琥胺","卡马西平"],"answer":2,"explanation":"乙琥胺是失神发作首选药；苯妥英钠对失神发作无效。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1634","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"左旋多巴治疗帕金森病的机制是？","options":["直接激动多巴胺受体","在脑内转变为多巴胺补充递质","抑制多巴胺降解","促进多巴胺释放"],"answer":1,"explanation":"左旋多巴透过血脑屏障，在脑内经多巴脱羧酶转变为多巴胺而发挥作用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1635","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"左旋多巴与卡比多巴合用的目的是？","options":["减少外周不良反应、增强脑内疗效","延长左旋多巴半衰期至24小时","直接激动多巴胺受体","促进左旋多巴排泄"],"answer":0,"explanation":"卡比多巴抑制外周多巴脱羧酶，使更多左旋多巴入脑，疗效增强、外周不良反应减少。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1636","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯丙嗪抗精神病的作用机制是？","options":["促进多巴胺释放","激动多巴胺受体","抑制5-HT受体","阻断中脑-边缘系统和中脑-皮质通路的多巴胺受体"],"answer":3,"explanation":"氯丙嗪通过阻断多巴胺受体（D2）发挥抗精神病作用，长期大量使用可致锥体外系反应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1637","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯丙嗪引起的锥体外系反应不包括？","options":["帕金森综合征","静坐不能","急性肌张力障碍","体位性低血压"],"answer":0,"explanation":"体位性低血压是α受体阻断所致，不属于锥体外系反应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1638","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"吗啡的药理作用不包括？","options":["呼吸兴奋","镇静","镇咳","镇痛"],"answer":3,"explanation":"吗啡有镇痛、镇静、镇咳、抑制呼吸等作用，对呼吸是抑制而非兴奋。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1639","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"吗啡禁用于？","options":["颅脑损伤所致颅内压增高者","心源性哮喘","严重创伤剧痛","晚期癌痛"],"answer":0,"explanation":"吗啡扩张脑血管、抑制呼吸，颅脑损伤颅内压增高者禁用；心源性哮喘可用吗啡辅助治疗。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1640","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"吗啡治疗心源性哮喘的机制不包括？","options":["增强心肌收缩力","镇静作用消除紧张情绪","降低呼吸中枢对CO2的敏感性，消除急促浅表呼吸","扩张外周血管，减轻心脏负荷"],"answer":3,"explanation":"吗啡不增强心肌收缩力，其治疗心源性哮喘靠扩血管、镇静和降低呼吸中枢兴奋性。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1641","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"哌替啶与吗啡比较，其特点是？","options":["成瘾性更强","镇痛作用更强","镇痛作用较弱、维持时间较短","抑制呼吸更明显"],"answer":2,"explanation":"哌替啶镇痛强度约为吗啡的1/10，维持时间短，是常用的人工合成镇痛药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1642","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"纳洛酮的作用是？","options":["阿片受体拮抗药，用于吗啡类中毒解救","阿片受体激动药","胆碱受体阻断药","呼吸兴奋药"],"answer":0,"explanation":"纳洛酮竞争性阻断阿片受体，是吗啡类镇痛药急性中毒的特效解救药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1643","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿司匹林解热镇痛抗炎的作用机制是？","options":["促进前列腺素合成","抑制前列腺素（PG）合成","阻断阿片受体","抑制组胺释放"],"answer":1,"explanation":"阿司匹林抑制环氧化酶（COX），减少前列腺素合成而发挥解热镇痛抗炎作用。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1644","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"小剂量阿司匹林预防血栓的机制是？","options":["促进纤溶","抑制血小板环氧化酶，减少血栓素A2生成","抑制凝血酶","增强血小板聚集"],"answer":1,"explanation":"小剂量阿司匹林不可逆抑制血小板COX，减少TXA2生成，抑制血小板聚集。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1645","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿司匹林最常见的不良反应是？","options":["胃肠道反应（恶心、呕吐、诱发溃疡）","肝肾损害","骨髓抑制","过敏休克"],"answer":0,"explanation":"阿司匹林最常见胃肠道反应，可诱发或加重胃溃疡，宜餐后服用。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1646","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"对乙酰氨基酚与阿司匹林比较，其特点是？","options":["更易引起胃溃疡","抗炎作用更强","几乎无抗炎抗风湿作用","抑制血小板聚集更强"],"answer":2,"explanation":"对乙酰氨基酚解热镇痛作用强而抗炎作用极弱，胃肠反应较轻。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1647","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"强心苷治疗心力衰竭的作用机制是？","options":["抑制心肌细胞钙内流","扩张血管减轻心脏负荷","阻断β受体","抑制心肌细胞膜Na+-K+-ATP酶，增强心肌收缩力"],"answer":3,"explanation":"强心苷抑制Na+-K+-ATP酶，使细胞内Na+增多、Na+-Ca2+交换减少、胞内Ca2+增多，心肌收缩力增强。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1648","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"强心苷最常见的心脏毒性反应是？","options":["室性早搏","房室传导阻滞","窦性心动过缓","心房颤动"],"answer":0,"explanation":"强心苷中毒最常见室性早搏（室性期前收缩），也可出现各类心律失常。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1649","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"地高辛中毒的常见诱发因素是？","options":["低血钙","高血钾","高血钙","低血钾"],"answer":3,"explanation":"低钾血症时心肌对强心苷敏感性增高，易诱发中毒，故用强心苷期间注意补钾。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1650","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"强心苷中毒的解救措施不包括？","options":["立即静脉注射钙剂","用苯妥英钠抗心律失常","用阿托品治疗房室传导阻滞","停药并补钾"],"answer":3,"explanation":"强心苷中毒时禁用钙剂（钙与强心苷协同加重毒性），其余为正确处理措施。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1651","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硝酸甘油抗心绞痛的主要机制是？","options":["扩张血管，降低心肌耗氧并增加缺血区供血","增强心肌收缩力","减慢心率","抗血小板聚集"],"answer":0,"explanation":"硝酸甘油扩张静脉减少前负荷、扩张冠状动脉增加缺血区供血，降低心肌耗氧。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1652","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硝酸甘油常用的给药途径是？","options":["口服","舌下含服","肌内注射","静脉推注"],"answer":1,"explanation":"硝酸甘油口服首过消除明显，舌下含服吸收快，是终止心绞痛发作的常用途径。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1653","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"普萘洛尔不宜用于下列哪种心绞痛？","options":["梗死后心绞痛","稳定型心绞痛","劳力型心绞痛","变异型心绞痛"],"answer":3,"explanation":"变异型心绞痛由冠脉痉挛引起，普萘洛尔阻断β受体使α受体占优势，可加重痉挛。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1654","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"钙通道阻滞药（硝苯地平）抗心绞痛的机制不包括？","options":["扩张冠状动脉","扩张外周血管降低心脏负荷","松弛支气管平滑肌","减弱心肌收缩力"],"answer":0,"explanation":"硝苯地平通过扩冠、降负荷、抑制心肌收缩力抗心绞痛，不松弛支气管平滑肌。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1655","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血管紧张素转换酶抑制剂（卡托普利）降压的特点不包括？","options":["降压同时不加快心率","长期用药不引起水钠潴留","可逆转心肌肥厚","明显升高血糖"],"answer":0,"explanation":"卡托普利降压平稳、可逆转心室重构，不会升高血糖；部分患者可致高血钾。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1656","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"卡托普利最常见的不良反应是？","options":["高血糖","心动过速","支气管痉挛","刺激性干咳"],"answer":3,"explanation":"ACEI抑制缓激肽降解，缓激肽增多刺激呼吸道引起刺激性干咳，为最常见不良反应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1657","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氢氯噻嗪的降压机制是？","options":["抑制血管紧张素转换酶","直接扩张小动脉","阻断α受体","早期排钠利尿减少血容量，长期用药降低血管平滑肌细胞内Na+和Ca2+"],"answer":3,"explanation":"噻嗪类利尿药早期通过排钠利尿减少血容量，长期用药使血管平滑肌细胞内钙减少而降压。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1658","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"噻嗪类利尿药长期应用最易引起？","options":["水中毒","高钾血症","低血糖","低钾血症"],"answer":3,"explanation":"氢氯噻嗪排钾利尿，长期应用易致低钾血症，需注意补钾。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1659","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硝普钠主要用于？","options":["变异型心绞痛的预防","轻度高血压","慢性心衰的长期口服治疗","高血压急症"],"answer":3,"explanation":"硝普钠起效快、作用强，静滴用于高血压急症和急性心衰。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1660","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"利多卡因主要用于治疗？","options":["室上性心动过速","室性心律失常","心房颤动","窦性心动过缓"],"answer":1,"explanation":"利多卡因是室性心律失常（尤其急性心梗并发的室性早搏、室速）的首选药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1661","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胺碘酮的主要不良反应不包括？","options":["肺纤维化","甲状腺功能紊乱","角膜色素沉着","血糖升高"],"answer":0,"explanation":"胺碘酮可致肺纤维化、甲亢或甲减、角膜色素沉着等，不影响血糖。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1662","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"治疗阵发性室上性心动过速急性发作首选？","options":["阿托品静注","利多卡因静注","胺碘酮口服","腺苷或维拉帕米静注"],"answer":3,"explanation":"腺苷（或维拉帕米）静注是终止阵发性室上速急性发作的首选。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1663","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿托品用于治疗下列哪种心律失常？","options":["心房颤动","室性心动过速","窦性心动过缓","室性早搏"],"answer":2,"explanation":"阿托品解除迷走神经对心脏的抑制，用于窦性心动过缓。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1664","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝素的抗凝机制是？","options":["促进纤维蛋白溶解","直接灭活凝血因子","抑制维生素K环氧化物还原酶","增强抗凝血酶Ⅲ的活性"],"answer":3,"explanation":"肝素与抗凝血酶Ⅲ结合，增强其灭活凝血因子Ⅱa、Ⅹa等的作用。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1665","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝素过量引起出血的解救药是？","options":["氨甲苯酸","维生素K","鱼精蛋白","酚磺乙胺"],"answer":2,"explanation":"鱼精蛋白为强碱性，与酸性肝素形成复合物使其失活，是肝素过量出血的特效解救药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1666","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"华法林的抗凝机制是？","options":["促进血小板解聚","增强抗凝血酶Ⅲ","直接抑制凝血酶","拮抗维生素K，抑制凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成"],"answer":3,"explanation":"华法林抑制维生素K依赖性凝血因子合成，起效慢，用于需长期抗凝者。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1667","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"华法林过量出血的解救药是？","options":["钙剂","鱼精蛋白","氨甲环酸","维生素K"],"answer":3,"explanation":"维生素K促进凝血因子合成，是华法林过量出血的解救药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1668","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"链激酶的作用是？","options":["抗血小板聚集","直接溶解纤维蛋白","抑制凝血酶","激活纤溶酶原转变为纤溶酶，溶解血栓"],"answer":3,"explanation":"链激酶激活纤溶系统，用于急性血栓栓塞性疾病（如心梗溶栓）。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1669","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"维生素K用于治疗？","options":["血友病甲","肝素过量出血","链激酶过量出血","华法林过量出血"],"answer":3,"explanation":"维生素K参与凝血因子合成，用于华法林过量及维生素K缺乏性出血。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1670","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"铁剂治疗缺铁性贫血的注意事项不包括？","options":["避免与牛奶同服","与维生素C同服促进吸收","避免与茶同服","与抗酸药同服促进吸收"],"answer":1,"explanation":"抗酸药减少铁的吸收，应避免同服；维C促进铁吸收，牛奶、茶妨碍吸收。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1671","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"口服铁剂最常见的胃肠道不良反应是？","options":["腹泻伴脱水","恶心、呕吐、上腹不适","便秘伴肠梗阻","剧烈腹痛"],"answer":1,"explanation":"口服铁剂常见恶心、呕吐、上腹不适等胃肠道刺激症状，宜餐后服。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1672","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"叶酸和维生素B12用于治疗？","options":["溶血性贫血","缺铁性贫血","再生障碍性贫血","巨幼细胞贫血"],"answer":3,"explanation":"叶酸和B12缺乏引起DNA合成障碍，导致巨幼细胞贫血。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1673","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"奥美拉唑治疗消化性溃疡的机制是？","options":["杀灭幽门螺杆菌","中和胃酸","保护胃黏膜","抑制胃壁细胞质子泵，减少胃酸分泌"],"answer":3,"explanation":"奥美拉唑为质子泵抑制剂，抑制胃酸分泌的最后环节，抑酸作用强而持久。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1674","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗幽门螺杆菌治疗常采用？","options":["单用铋剂","单用一种抗生素","质子泵抑制剂+两种抗生素的三联疗法","单用抗酸药"],"answer":2,"explanation":"根除幽门螺杆菌需联合用药，常用PPI+阿莫西林+克拉霉素等三联或四联方案。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1675","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硫糖铝的作用是？","options":["在胃黏膜表面形成保护膜","中和胃酸","抑制胃酸分泌","促进胃排空"],"answer":0,"explanation":"硫糖铝在酸性环境中聚合成保护膜，覆盖溃疡面促进愈合。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1676","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"异丙嗪属于？","options":["质子泵抑制剂","H2受体阻断药","H1受体阻断药","M受体阻断药"],"answer":2,"explanation":"异丙嗪为第一代H1受体阻断药，用于过敏性疾病，有中枢镇静作用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1677","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖皮质激素的药理作用不包括？","options":["抗休克","抗过敏","抗炎","升高血糖为治疗目的"],"answer":2,"explanation":"糖皮质激素有抗炎、抗过敏、抗休克、免疫抑制等作用，升高血糖是其代谢不良反应而非治疗目的。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1678","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖皮质激素隔日疗法的目的是？","options":["增强抗炎效果","减少对肾上腺皮质功能的抑制","延长作用时间","减少胃肠道反应"],"answer":1,"explanation":"隔日晨间给药符合皮质激素分泌节律，减轻对垂体-肾上腺轴的抑制。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1679","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"长期应用糖皮质激素突然停药可引起？","options":["反跳现象与肾上腺皮质功能不全","戒断性抽搐","永久性高血压","甲状腺危象"],"answer":0,"explanation":"突然停药致病情反跳和肾上腺皮质功能不全，应逐渐减量停药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1680","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖皮质激素诱发或加重感染的原因是？","options":["直接损伤黏膜","促进细菌繁殖","抑制免疫功能","升高体温"],"answer":2,"explanation":"糖皮质激素抑制免疫炎症反应，降低机体防御能力，可诱发或加重感染。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1681","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胰岛素最严重的不良反应是？","options":["注射部位脂肪萎缩","过敏反应","胰岛素抵抗","低血糖反应"],"answer":3,"explanation":"胰岛素过量引起低血糖，严重者可致昏迷，是最常见也最严重的不良反应。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1682","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"磺酰脲类降糖药的主要作用机制是？","options":["促进葡萄糖利用","刺激胰岛β细胞释放胰岛素","抑制葡萄糖吸收","增强胰岛素敏感性"],"answer":1,"explanation":"磺酰脲类（格列本脲等）通过刺激残存胰岛β细胞分泌胰岛素降血糖。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1683","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"二甲双胍的主要作用机制是？","options":["补充胰岛素","刺激胰岛素分泌","增强外周组织对胰岛素的敏感性、减少糖异生","抑制胰高血糖素分泌"],"answer":2,"explanation":"二甲双胍不刺激胰岛素分泌，通过增敏、减少肝糖输出等降糖，单用不易致低血糖。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1684","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"双胍类降糖药最严重的不良反应是？","options":["乳酸酸中毒","低血糖","过敏反应","肝功能损害"],"answer":0,"explanation":"二甲双胍严重不良反应为乳酸酸中毒（多见于肾功能不全者），常见反应为胃肠道反应。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1685","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"异烟肼最常见的不良反应是？","options":["周围神经炎","耳毒性","肾毒性","骨髓抑制"],"answer":0,"explanation":"异烟肼可致周围神经炎（与维生素B6缺乏有关），长期用药宜加服维生素B6。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1686","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"利福平的抗结核特点是？","options":["仅抑菌","单用不易耐药","抑菌兼杀菌，易产生耐药性宜联合用药","只对细胞外结核菌有效"],"answer":2,"explanation":"利福平抗菌谱广，对结核杆菌有强大杀菌作用，单用易耐药，必须联合用药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1687","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗结核病药联合用药的主要目的是？","options":["缩短疗程至一周","减少给药次数","降低药物价格","延缓耐药性产生、增强疗效"],"answer":3,"explanation":"联合用药可增强疗效、延缓耐药性产生，是结核病化疗的基本原则。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1688","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙胺丁醇的特征性不良反应是？","options":["肾毒性","周围神经炎","耳毒性","球后视神经炎"],"answer":3,"explanation":"乙胺丁醇长期大量应用可致球后视神经炎，表现为视力下降、红绿色盲。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1689","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲硝唑对下列哪类感染无效？","options":["真菌感染","厌氧菌感染","阴道滴虫","阿米巴原虫"],"answer":0,"explanation":"甲硝唑对厌氧菌、滴虫、阿米巴有效，对真菌无效。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1690","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"喹诺酮类（左氧氟沙星）不宜用于？","options":["成人呼吸道感染","18岁以下儿童","泌尿道感染成人患者","肠道感染成人患者"],"answer":1,"explanation":"喹诺酮类影响软骨发育，18岁以下儿童、孕妇、哺乳期妇女禁用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1691","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"头孢菌素类药物的主要不良反应是？","options":["耳毒性","过敏反应","骨髓抑制","周围神经炎"],"answer":1,"explanation":"头孢菌素类可致过敏反应（与青霉素有部分交叉过敏），肾毒性较第一代明显者需注意。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1692","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氨基糖苷类抗生素最突出的不良反应是？","options":["肝毒性","胃肠道反应","过敏休克","耳毒性和肾毒性"],"answer":3,"explanation":"氨基糖苷类（庆大霉素、链霉素等）主要不良反应为耳毒性（听神经损害）和肾毒性。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1693","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"四环素类不宜用于8岁以下儿童的原因是？","options":["影响牙齿和骨骼发育","引起耳聋","损伤肾小管","抑制骨髓"],"answer":0,"explanation":"四环素类沉积于牙和骨骼，致牙齿黄染（四环素牙）并影响骨骼发育。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1694","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯霉素最严重的不良反应是？","options":["抑制骨髓造血功能（再生障碍性贫血）","胃肠道反应","灰婴综合征","过敏反应"],"answer":0,"explanation":"氯霉素可抑制骨髓造血，个别患者发生致死性再生障碍性贫血，是其最严重不良反应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1695","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗恶性肿瘤药共有的主要不良反应是？","options":["耳毒性","骨髓抑制、胃肠道反应、脱发","肾结石","周围神经炎"],"answer":1,"explanation":"抗肿瘤药杀伤增殖细胞，骨髓、消化道黏膜、毛囊等更新快的组织最易受损。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1696","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"环磷酰胺的特征性不良反应是？","options":["肺纤维化","出血性膀胱炎","周围神经炎","牙龈增生"],"answer":1,"explanation":"环磷酰胺代谢物刺激膀胱，可致出血性膀胱炎，用药期间应多饮水。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1697","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"顺铂的主要剂量限制性毒性是？","options":["肾毒性","心脏毒性","肺纤维化","便秘"],"answer":0,"explanation":"顺铂肾毒性明显，用药需水化利尿以保护肾脏。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1698","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"紫杉醇给药前需预防性使用？","options":["糖皮质激素和抗组胺药","抗生素","止血药","利尿药"],"answer":0,"explanation":"紫杉醇可致严重过敏反应（溶媒所致），给药前需用糖皮质激素、抗组胺药预处理。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1699","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物在体内发生的化学结构变化称为？","options":["吸收","生物转化（代谢）","分布","排泄"],"answer":1,"explanation":"生物转化指药物在酶作用下发生化学结构变化，多在肝脏进行。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1700","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物经肾脏排泄的主要方式是？","options":["肾小球囊内吞","肾小管重吸收","集合管分泌","肾小球滤过和肾小管分泌"],"answer":3,"explanation":"药物及其代谢物主要经肾小球滤过和肾小管分泌排出。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1701","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"碱性药物中毒时，为加速排泄应？","options":["碱化尿液","酸化尿液","大量饮水即可","禁食"],"answer":1,"explanation":"酸化尿液使碱性药物解离增多、重吸收减少，排泄加快。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1702","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物主动转运的特点是？","options":["需要载体、耗能、有饱和现象","顺浓度梯度扩散","不耗能","无饱和现象"],"answer":0,"explanation":"主动转运逆浓度梯度、需载体和能量，有饱和与竞争抑制现象。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1703","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"药物被动转运的特点是？","options":["需载体耗能","逆浓度梯度","顺浓度梯度、不耗能","有饱和现象"],"answer":2,"explanation":"被动转运（简单扩散）顺浓度梯度进行，不耗能、无饱和现象。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1704","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"影响药物吸收的因素不包括？","options":["给药途径","血浆蛋白结合率","胃肠道pH","药物溶解度"],"answer":1,"explanation":"血浆蛋白结合率影响分布，不影响吸收。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1705","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"皮下注射比口服吸收快的原因是？","options":["药物极性更小","药物剂量更大","直接进入体循环，避免首过消除","胃肠道pH更适宜"],"answer":2,"explanation":"注射给药绕过胃肠道和肝脏，吸收快而完全。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1706","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素类的作用机制是？","options":["影响细菌细胞膜通透性","抑制细菌蛋白质合成","抑制细菌核酸合成","抑制细菌细胞壁合成"],"answer":3,"explanation":"青霉素抑制转肽酶，阻碍细菌细胞壁黏肽合成，属繁殖期杀菌剂。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1707","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素抗菌谱的特点是？","options":["对革兰阴性杆菌作用强","主要对革兰阳性菌有效","对支原体作用强","对真菌有效"],"answer":1,"explanation":"青霉素主要作用于革兰阳性菌及少数革兰阴性菌（如脑膜炎奈瑟菌），对多数革兰阴性杆菌无效。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1708","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素皮试阳性的处理是？","options":["减量使用","脱敏后使用","禁用青霉素，改用其他药物","加用抗过敏药后使用"],"answer":2,"explanation":"皮试阳性者禁用青霉素，必须更换其他抗菌药物。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1709","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素最需要警惕的不良反应是？","options":["胃肠道反应","过敏性休克","耳毒性","肾毒性"],"answer":1,"explanation":"过敏性休克发生急骤、可致死，用药前必须询问过敏史并做皮试，药液现配现用。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1710","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"头孢曲松属于第几代头孢菌素？","options":["第一代","第三代","第二代","第四代"],"answer":1,"explanation":"头孢曲松为第三代头孢菌素，对革兰阴性菌作用强，可透过血脑屏障。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1711","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"第一代头孢菌素的特点是？","options":["抗厌氧菌作用强","对革兰阴性菌作用最强","无肾毒性","主要对革兰阳性菌作用强、有一定肾毒性"],"answer":3,"explanation":"第一代头孢（头孢唑林等）抗革兰阳性菌作用强，肾毒性较明显。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1712","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"红霉素属于？","options":["β-内酰胺类","大环内酯类抗生素","氨基糖苷类","四环素类"],"answer":1,"explanation":"红霉素为大环内酯类，主要作用于革兰阳性菌及支原体、衣原体。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1713","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"大环内酯类的主要不良反应是？","options":["耳毒性","胃肠道反应","骨髓抑制","出血"],"answer":1,"explanation":"红霉素类常见恶心、呕吐、腹痛等胃肠道反应，静滴可致血栓性静脉炎。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1714","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"庆大霉素的主要给药途径是？","options":["皮下注射","口服","肌内注射或静脉滴注","雾化吸入"],"answer":2,"explanation":"庆大霉素口服几乎不吸收（仅用于肠道感染），全身感染需注射给药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1715","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"链霉素对下列哪种感染是首选？","options":["肺炎链球菌肺炎","鼠疫和兔热病","伤寒","梅毒"],"answer":1,"explanation":"链霉素是鼠疫和兔热病（土拉菌病）的首选药，也用于结核病联合化疗。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1716","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"多西环素属于？","options":["磺胺类","大环内酯类","喹诺酮类","四环素类"],"answer":3,"explanation":"多西环素为半合成四环素类，抗菌作用强于四环素，肾功能不全者可选用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1717","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"磺胺类药物的作用机制是？","options":["抑制细菌DNA回旋酶","抑制细菌二氢叶酸合成酶","抑制细胞壁合成","抑制蛋白质合成"],"answer":1,"explanation":"磺胺类为叶酸代谢抑制剂（抑菌剂），与PABA结构相似而竞争二氢叶酸合成酶。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1718","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"服用磺胺类药物时需碱化尿液的原因是？","options":["防止磺胺结晶析出损伤肾脏","增强抗菌活性","促进药物吸收","减少胃肠道反应"],"answer":0,"explanation":"磺胺药及其乙酰化物在酸性尿中易结晶，碱化尿液可防止肾损害。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1719","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"喹诺酮类的作用机制是？","options":["抑制细菌DNA回旋酶","抑制二氢叶酸合成酶","抑制细胞壁合成","抑制蛋白质合成"],"answer":0,"explanation":"喹诺酮类抑制DNA回旋酶（拓扑异构酶Ⅱ），阻碍DNA复制，为杀菌剂。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1720","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"环丙沙星对下列哪种病原体作用较弱？","options":["流感嗜血杆菌","铜绿假单胞菌","大肠埃希菌","厌氧菌"],"answer":3,"explanation":"多数喹诺酮类对厌氧菌作用弱，主要抗革兰阴性菌及部分阳性菌。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1721","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"异烟肼抗结核的作用特点是？","options":["不能透过血脑屏障","仅抑菌","杀菌作用强、穿透力强、可进入脑脊液","毒性极小无需监测"],"answer":2,"explanation":"异烟肼对结核杆菌杀菌作用强，穿透力强，是各型结核病的基础用药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1722","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"吡嗪酰胺的主要不良反应是？","options":["周围神经炎","耳毒性","肝损害和高尿酸血症","出血"],"answer":2,"explanation":"吡嗪酰胺可致肝损害和血尿酸升高（诱发痛风），肝功能不全者慎用。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1723","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙胺丁醇用药期间需定期检查？","options":["听力","视力和视野","肾功能","血常规"],"answer":1,"explanation":"乙胺丁醇可致球后视神经炎，用药期间定期检查视力、视野和色觉。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1724","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗结核化疗的原则是？","options":["症状消失即停药","大剂量冲击","单药长程","早期、联合、适量、规律、全程"],"answer":3,"explanation":"结核病化疗必须遵循早期、联合、适量、规律、全程十字原则。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1725","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"伯氨喹的主要作用是？","options":["预防疟疾感染","杀灭红内期裂殖体，控制症状","杀灭疟原虫红外期和配子体，控制复发与传播","杀灭疟原虫子孢子"],"answer":2,"explanation":"伯氨喹杀灭肝内休眠子和配子体，用于根治间日疟和阻断传播；氯喹控制发作。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1726","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯喹的主要作用是？","options":["杀灭休眠子","根治疟疾","防止传播","杀灭红内期疟原虫，迅速控制疟疾发作"],"answer":3,"explanation":"氯喹杀灭红内期裂殖体，是控制疟疾症状发作的首选药。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1727","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿苯达唑的主要用途是？","options":["驱肠道线虫（蛔虫、钩虫、蛲虫等）","抗疟","抗真菌","抗结核"],"answer":0,"explanation":"阿苯达唑为广谱驱虫药，对蛔虫、钩虫、蛲虫、绦虫等有效。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1728","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氨茶碱平喘的机制是？","options":["激动β2受体","抑制磷酸二酯酶，升高细胞内cAMP","阻断M受体","抑制组胺释放"],"answer":1,"explanation":"氨茶碱抑制磷酸二酯酶使cAMP增多，舒张支气管平滑肌，兼有强心利尿作用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1729","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氨茶碱静滴过快的主要危险是？","options":["肝损害","低血压","便秘","心律失常、惊厥"],"answer":3,"explanation":"氨茶碱安全范围窄，静滴过快可致心律失常、惊厥甚至死亡，需缓慢滴注。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1730","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"沙丁胺醇平喘的机制是？","options":["选择性激动支气管β2受体","阻断M受体","抑制磷酸二酯酶","阻断组胺受体"],"answer":0,"explanation":"沙丁胺醇为选择性β2受体激动剂，舒张支气管平滑肌，心血管不良反应较轻。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1731","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"色甘酸钠的作用是？","options":["稳定肥大细胞膜，预防哮喘发作","舒张支气管平滑肌","抗炎抗过敏","稀释痰液"],"answer":0,"explanation":"色甘酸钠抑制肥大细胞脱颗粒，主要用于预防哮喘发作，对发作期无效。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1732","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"镇咳药可待因的作用特点是？","options":["稀释痰液","外周性镇咳","中枢性镇咳作用强，有成瘾性","扩张支气管"],"answer":2,"explanation":"可待因直接抑制延髓咳嗽中枢，镇咳作用强，反复应用可成瘾，严格控制使用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1733","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯化铵属于？","options":["中枢性镇咳药","恶心性祛痰药","外周性镇咳药","平喘药"],"answer":1,"explanation":"氯化铵刺激胃黏膜引起恶心，反射性促进支气管腺体分泌，稀释痰液。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1734","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"缩宫素用于？","options":["抑制宫缩","保胎","治疗痛经","产后止血和引产"],"answer":3,"explanation":"缩宫素兴奋子宫平滑肌，小剂量用于催产引产，大剂量用于产后止血。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1735","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"麦角新碱用于？","options":["催产","产后子宫出血（促进子宫强直性收缩）","引产","保胎"],"answer":1,"explanation":"麦角新碱使子宫持续强直收缩，只用于产后止血，禁用于催产引产。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1736","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"缩宫素用于催产时的注意事项不包括？","options":["有头盆不称者禁用","密切观察宫缩与胎心","严格掌握剂量避免子宫强直收缩","大剂量快速静滴以缩短产程"],"answer":2,"explanation":"催产时小剂量缓慢滴注并严密监护；大剂量快速滴注可致子宫破裂、胎儿窘迫。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1737","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"维生素D用于防治？","options":["脚气病","坏血病","佝偻病和骨软化症","夜盲症"],"answer":2,"explanation":"维生素D促进钙磷吸收与骨盐沉积，用于防治佝偻病、骨软化症。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1738","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"维生素C用于防治？","options":["脚气病","佝偻病","夜盲症","坏血病"],"answer":3,"explanation":"维生素C缺乏引起坏血病（毛细血管脆性增加、出血）。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1739","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"维生素A用于防治？","options":["夜盲症","坏血病","佝偻病","脚气病"],"answer":0,"explanation":"维生素A参与视紫红质合成，缺乏致夜盲症、干眼病。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1740","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"维生素B1用于防治？","options":["佝偻病","坏血病","脚气病","夜盲症"],"answer":2,"explanation":"维生素B1缺乏引起脚气病（周围神经炎、心功能不全等）。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1741","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"右旋糖酐的主要作用是？","options":["扩充血容量（低分子右旋糖酐兼有抗凝作用）","补充营养","纠正酸中毒","利尿"],"answer":0,"explanation":"右旋糖酐提高血浆胶体渗透压扩充血容量，低分子者还抑制红细胞和血小板聚集。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1742","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"西地那非类药物治疗勃起功能障碍的禁忌是？","options":["高血压患者","正在服用硝酸酯类药物者","糖尿病患者","老年人"],"answer":1,"explanation":"硝酸酯类与该药合用可致严重低血压，绝对禁忌。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1743","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"缩宫素引产时最严重的并发症是？","options":["子宫破裂","产后出血","感染","羊水过少"],"answer":0,"explanation":"缩宫素过量致子宫强直性收缩，可发生子宫破裂、胎儿窘迫。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1744","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硫酸镁用于妊娠高血压的主要作用机制是？","options":["抑制醛固酮","利尿降压","镁离子拮抗钙离子，解除血管痉挛","阻断α受体"],"answer":2,"explanation":"硫酸镁中镁离子拮抗钙离子，松弛血管平滑肌，是子痫前期解痉首选。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1745","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硫酸镁中毒的解救药是？","options":["葡萄糖酸钙","氯化钾","碳酸氢钠","维生素K"],"answer":0,"explanation":"镁离子中毒用钙剂（葡萄糖酸钙）拮抗解救。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1746","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"缩宫素的禁忌证不包括？","options":["前置胎盘","胎位异常","头盆不称","产后子宫收缩乏力出血"],"answer":2,"explanation":"产后宫缩乏力出血是缩宫素的适应证；头盆不称、胎位异常、前置胎盘等为禁忌。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1747","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"治疗子痫首选的解痉药物是？","options":["肼屈嗪","地西泮","硝苯地平","硫酸镁"],"answer":3,"explanation":"硫酸镁是子痫前期-子痫解痉治疗的首选药物。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1748","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"催产素引产失败最常见的原因是？","options":["羊水过多","胎儿过大","宫颈不成熟","产妇年龄大"],"answer":2,"explanation":"宫颈Bishop评分低（宫颈不成熟）是引产失败最常见原因。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1749","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"麦角新碱禁用于催产的原因是？","options":["引起子宫强直性收缩致胎儿窘迫、子宫破裂","作用太弱","半衰期太长","过敏率高"],"answer":0,"explanation":"麦角新碱引起子宫持续强直收缩，产程中使用可致子宫破裂和胎儿缺氧。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1750","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"维生素K3的给药途径是？","options":["动脉注射","静脉推注","皮下注射","肌内注射（口服需用缓释剂型）"],"answer":3,"explanation":"维生素K3、K4为人工合成水溶性制剂，刺激性大，需肌注或口服缓释剂型，静注过快可致血压骤降。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1751","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"垂体后叶素用于肺咯血的作用机制是？","options":["抑制纤溶酶原激活","促进凝血因子合成","抗纤维蛋白溶解","收缩肺小动脉，减少出血"],"answer":3,"explanation":"垂体后叶素含加压素，收缩肺小动脉和毛细血管，用于大咯血急救。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1752","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"垂体后叶素的禁忌证不包括？","options":["妊娠","高血压","冠心病","支气管扩张咯血"],"answer":2,"explanation":"垂体后叶素收缩冠脉和升高血压，冠心病、高血压、妊娠者禁用；支气管扩张咯血是其适应证。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1753","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氨甲苯酸的作用机制是？","options":["抗血小板聚集","促进凝血因子合成","收缩血管","抑制纤维蛋白溶解（抗纤溶药）"],"answer":3,"explanation":"氨甲苯酸抑制纤溶酶原激活，用于纤溶亢进所致出血。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1754","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝素在体内的抗凝特点不包括？","options":["起效快","口服有效","体内体外均抗凝","主要经肝代谢"],"answer":1,"explanation":"肝素口服不吸收，需注射给药，体内体外均有抗凝作用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1755","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"枸橼酸钠的抗凝机制是？","options":["络合钙离子，阻止凝血","拮抗维生素K","增强抗凝血酶Ⅲ","抑制血小板聚集"],"answer":0,"explanation":"枸橼酸钠与血中钙离子络合，用于体外抗凝（如血液保存）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1756","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"华法林抗凝的起效时间是？","options":["立即起效","用药后24-72小时起效","1周后起效","2周后起效"],"answer":1,"explanation":"华法林需待体内原有凝血因子耗竭后才起效，一般24-72小时。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1757","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低分子肝素与普通肝素比较，其特点是？","options":["出血不良反应较少、不需常规监测APTT","出血更多","半衰期更短","抗凝作用更强"],"answer":0,"explanation":"低分子肝素抑制Ⅹa为主，出血风险较低，使用方便。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1758","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿司匹林抗血栓的适宜剂量是？","options":["大剂量（3-5g/日）","小剂量（75-100mg/日）","中剂量（1g/日）","任意剂量"],"answer":1,"explanation":"小剂量阿司匹林选择性抑制血小板TXA2，大剂量反而抑制前列环素合成、减弱抗栓效果。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1759","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"双嘧达莫的抗栓机制是？","options":["溶解血栓","阻断血小板ADP受体","抑制凝血酶","抑制磷酸二酯酶，升高血小板cAMP"],"answer":3,"explanation":"双嘧达莫抑制磷酸二酯酶和腺苷摄取，使血小板cAMP增多而抑制聚集。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1760","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯吡格雷的作用机制是？","options":["溶解纤维蛋白","抑制环氧化酶","增强抗凝血酶Ⅲ","阻断血小板ADP受体（P2Y12）"],"answer":3,"explanation":"氯吡格雷选择性阻断血小板ADP受体，抑制血小板聚集，用于动脉血栓防治。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1761","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"右旋糖酐禁用于？","options":["低血容量休克","严重血小板减少和出血性疾病","血液高凝状态","术后血栓预防"],"answer":1,"explanation":"右旋糖酐抑制血小板功能，出血性疾病患者禁用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1762","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"叶酸拮抗药甲氨蝶呤中毒的解救药是？","options":["维生素B12","亚叶酸钙","维生素C","维生素K"],"answer":1,"explanation":"亚叶酸钙（甲酰四氢叶酸钙）提供四氢叶酸，解救甲氨蝶呤对叶酸代谢的阻断。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1763","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"治疗缺铁性贫血铁剂疗效最早的指标是？","options":["血清铁正常","血红蛋白升高","红细胞计数正常","网织红细胞计数升高"],"answer":3,"explanation":"服铁剂后3-4天网织红细胞开始升高，是疗效出现最早的指标。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1764","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"铁剂治疗缺铁性贫血，血红蛋白正常后仍需继续服药的原因是？","options":["促进白细胞生成","防止药物依赖","补足体内储存铁","预防感染"],"answer":2,"explanation":"血红蛋白恢复正常后仍需继续服药2-3个月，补足储存铁防止复发。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1765","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"再生障碍性贫血的治疗不包括？","options":["雄激素","铁剂","免疫抑制剂","造血干细胞移植"],"answer":1,"explanation":"再障是造血干细胞损伤，不是缺铁，铁剂无效。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1766","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"维生素K参与合成的凝血因子是？","options":["Ⅱ、Ⅶ、Ⅸ、Ⅹ","Ⅰ、Ⅲ、Ⅴ、Ⅻ","Ⅴ、Ⅷ、Ⅺ、Ⅻ","Ⅰ、Ⅱ、Ⅴ、Ⅷ"],"answer":0,"explanation":"维生素K依赖性凝血因子为Ⅱ、Ⅶ、Ⅸ、Ⅹ。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1767","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝素抗凝作用最强的给药途径是？","options":["口服","肌内注射","皮下注射","静脉给药"],"answer":3,"explanation":"肝素口服不吸收，静注立即起效，抗凝作用最强。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1768","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"双香豆素类药物与苯巴比妥合用后？","options":["抗凝作用减弱","抗凝作用增强","无相互影响","出血风险增大"],"answer":0,"explanation":"苯巴比妥为肝药酶诱导剂，加速华法林代谢，抗凝作用减弱。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1769","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"奥美拉唑长期应用需注意？","options":["必然导致胃癌","可能引起维生素B12吸收减少","永久性胃酸缺乏","骨质疏松不可避免"],"answer":1,"explanation":"长期抑酸可影响维生素B12吸收和钙吸收，需注意监测，非必然发生。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1770","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"多潘立酮（吗丁啉）的作用是？","options":["促进胃动力（外周多巴胺受体阻断）","抑制胃酸","保护胃黏膜","止泻"],"answer":0,"explanation":"多潘立酮阻断外周多巴胺受体，促进胃排空，用于功能性消化不良。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1771","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乳酶生的作用是？","options":["杀灭肠道细菌","补充肠道正常菌群（活乳酸杆菌制剂）","中和胃酸","止吐"],"answer":1,"explanation":"乳酶生为活乳酸杆菌制剂，抑制腐败菌繁殖、促进消化，不宜与抗菌药同服。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1772","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"微生态制剂（双歧杆菌制剂）不宜与什么同服？","options":["钙剂","维生素","抗菌药物","胃黏膜保护剂"],"answer":2,"explanation":"抗菌药物可杀灭活菌制剂，应间隔服用。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1773","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硫酸镁口服的作用是？","options":["抗惊厥","镇静","导泻","降压"],"answer":2,"explanation":"口服硫酸镁不被吸收，形成高渗刺激肠蠕动而导泻；注射才有镇静降压作用。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1774","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硫酸镁注射给药的作用是？","options":["导泻","抗惊厥、降血压","利胆","通便"],"answer":1,"explanation":"注射硫酸镁抑制中枢和神经肌肉传导，用于子痫、惊厥和高血压危象。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1775","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"开塞露的主要成分是？","options":["乳果糖","硫酸镁","酚酞","甘油（山梨醇）"],"answer":3,"explanation":"开塞露为甘油制剂，润滑并刺激肠壁，用于便秘临时通便。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1776","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"酚酞属于？","options":["止泻药","润滑性泻药","容积性泻药","刺激性泻药"],"answer":3,"explanation":"酚酞刺激结肠黏膜促进蠕动，属刺激性泻药，长期使用可致依赖。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1777","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"蒙脱石散止泻的机制是？","options":["中和胃酸","抑制肠蠕动","杀灭细菌","覆盖消化道黏膜，吸附病原体和毒素"],"answer":3,"explanation":"蒙脱石散天然硅酸盐制剂，覆盖保护黏膜并吸附病原，不抑制肠蠕动。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1778","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"地芬诺酯止泻的机制是？","options":["吸附毒素","抑制肠道平滑肌蠕动（类似阿片作用）","调节菌群","保护黏膜"],"answer":1,"explanation":"地芬诺酯为哌替啶衍生物，直接作用于肠道阿片受体，减少肠蠕动。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1779","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"昂丹司琼止吐的机制是？","options":["阻断多巴胺受体","阻断5-HT3受体","阻断组胺受体","抑制呕吐中枢代谢"],"answer":1,"explanation":"昂丹司琼为5-HT3受体阻断药，用于化疗、放疗所致呕吐，效果好。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1780","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯丙嗪止吐的特点是？","options":["对晕动病（晕车）所致呕吐无效","对所有呕吐均有效","只对晕动病有效","促进胃排空"],"answer":0,"explanation":"氯丙嗪抑制催吐化学感受区，对药物、妊娠等呕吐有效，对前庭刺激所致晕动病无效。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1781","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"组胺的生理作用不包括？","options":["扩张血管","增加毛细血管通透性","收缩支气管平滑肌","收缩瞳孔"],"answer":0,"explanation":"组胺扩张血管、增通透性、收缩支气管和胃肠平滑肌，不收缩瞳孔。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1782","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"H1受体阻断药最常见的中枢作用是？","options":["镇静催眠","兴奋躁动","呼吸抑制","惊厥"],"answer":0,"explanation":"第一代H1阻断药（苯海拉明、异丙嗪）有中枢镇静作用，第二代（氯雷他定）中枢作用弱。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1783","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯雷他定与苯海拉明比较，优点是？","options":["中枢镇静作用弱","抗过敏作用更强","起效更慢","半衰期更短"],"answer":0,"explanation":"氯雷他定为第二代H1阻断药，不易透过血脑屏障，中枢镇静作用弱。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1784","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"钙剂抗过敏的机制是？","options":["阻断组胺受体","降低毛细血管通透性","抑制组胺合成","稳定溶酶体膜"],"answer":1,"explanation":"钙剂降低毛细血管通透性、减少渗出，辅助治疗过敏性疾病。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1785","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"色甘酸钠的给药途径是？","options":["肌内注射","口服","吸入给药","静脉注射"],"answer":2,"explanation":"色甘酸钠口服吸收差，采用吸入（粉雾）给药预防哮喘发作。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1786","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氨茶碱治疗心源性哮喘的机制不包括？","options":["利尿","扩张支气管","增强心肌收缩力","扩张血管"],"answer":2,"explanation":"氨茶碱有强心、利尿、扩张血管和支气管作用，不直接增强心肌收缩力（其强心作用与抑制磷酸二酯酶有关，但机制描述以正性肌力为辅）。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1787","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"特布他林属于？","options":["β2受体激动药","β1受体激动药","α受体激动药","M受体激动药"],"answer":0,"explanation":"特布他林为选择性β2受体激动剂，用于支气管哮喘。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1788","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"异丙托溴铵平喘的机制是？","options":["抑制磷酸二酯酶","激动β2受体","阻断支气管M受体","抗炎"],"answer":2,"explanation":"异丙托溴铵为阿托品衍生物，阻断M受体舒张支气管，适用于不能耐受β2激动剂者。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1789","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"布地奈德属于？","options":["白三烯调节剂","β2受体激动药","吸入性糖皮质激素","茶碱类"],"answer":2,"explanation":"布地奈德为局部吸入用糖皮质激素，是哮喘长期控制的首选抗炎药。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1790","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"白三烯调节剂（孟鲁司特）的作用是？","options":["中和过敏原","扩张支气管立即起效","阻断白三烯受体，用于哮喘预防","抑制咳嗽反射"],"answer":2,"explanation":"孟鲁司特阻断白三烯受体，减轻气道炎症，用于哮喘预防和阿司匹林哮喘。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1791","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"酮替芬的作用是？","options":["兼有抗组胺和稳定肥大细胞膜作用","单纯扩张支气管","糖皮质激素作用","镇咳"],"answer":0,"explanation":"酮替芬为H1阻断药兼抑制肥大细胞释放介质，用于预防哮喘和过敏性鼻炎。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1792","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"哮喘持续状态不宜使用的药物是？","options":["沙丁胺醇","糖皮质激素","氨茶碱","吗啡"],"answer":3,"explanation":"吗啡抑制呼吸中枢并释放组胺收缩支气管，哮喘患者禁用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1793","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"治疗过敏性休克除肾上腺素外还可辅用？","options":["去甲肾上腺素","糖皮质激素","阿托品","毛果芸香碱"],"answer":1,"explanation":"糖皮质激素抗过敏抗休克，作为过敏性休克的辅助治疗药物。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1794","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素过敏性休克最主要的死亡原因是？","options":["肾衰竭","心律失常","喉头水肿和支气管痉挛致窒息","脑出血"],"answer":2,"explanation":"青霉素过敏性休克死于喉头水肿、支气管痉挛（窒息）和循环衰竭。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1795","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风抗毒素（TAT）皮试阳性的正确处理是？","options":["加大剂量注射","直接注射","改用青霉素","采用脱敏注射或用人破伤风免疫球蛋白"],"answer":3,"explanation":"TAT皮试阳性者采用脱敏注射（分次增量）或改用人破伤风免疫球蛋白。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1796","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风抗毒素属于？","options":["疫苗","类毒素","抗生素","特异性抗体（被动免疫制剂）"],"answer":3,"explanation":"TAT是马血清制备的特异性抗体，属被动免疫，可引起过敏反应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1797","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风类毒素属于？","options":["抗生素","被动免疫制剂","主动免疫制剂（疫苗）","抗毒素"],"answer":2,"explanation":"类毒素刺激机体产生抗体，属主动免疫，用于预防接种。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1798","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"干扰素的主要作用不包括？","options":["抗肿瘤","抗病毒","直接杀灭细菌","免疫调节"],"answer":2,"explanation":"干扰素抗病毒、抗肿瘤、免疫调节，对细菌无直接杀灭作用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1799","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿昔洛韦的作用机制是？","options":["阻断病毒吸附","抑制病毒RNA聚合酶","抑制病毒DNA聚合酶","抑制病毒蛋白质合成"],"answer":2,"explanation":"阿昔洛韦在感染细胞内转变为三磷酸形式，抑制病毒DNA聚合酶，对疱疹病毒有效。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1800","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"革兰阳性菌与革兰阴性菌细胞壁的主要区别成分是？","options":["磷壁酸（阳性菌特有）","外膜（阴性菌特有）","脂多糖","肽聚糖"],"answer":0,"explanation":"革兰阳性菌细胞壁含大量磷壁酸，革兰阴性菌有外膜和脂多糖，两者共有肽聚糖。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1801","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"革兰阴性菌的内毒素成分是？","options":["外毒素","脂多糖（LPS）","磷壁酸","荚膜"],"answer":1,"explanation":"革兰阴性菌内毒素即细胞壁外膜的脂多糖，菌体裂解后释放。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1802","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"内毒素的特点是？","options":["可经甲醛脱毒制成类毒素","不耐热、毒性强","耐热、毒性较弱、不能制成类毒素","对组织有选择性毒性作用"],"answer":2,"explanation":"内毒素耐热、毒性较外毒素弱、无组织选择性，甲醛处理不能脱毒制成类毒素。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1803","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"外毒素的特点是？","options":["由革兰阴性菌裂解产生","耐热性强","毒性强、有组织选择性、可制成类毒素","不能制成类毒素"],"answer":2,"explanation":"外毒素多为革兰阳性菌分泌的蛋白质，毒性强且有组织选择性，甲醛脱毒后可制成类毒素（疫苗）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1804","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌芽孢的特点是？","options":["只存在于革兰阴性菌","是细菌的繁殖方式","对热和干燥抵抗力强","与细菌致病力直接相关"],"answer":2,"explanation":"芽孢是细菌的休眠体，耐热性强，是灭菌效果的评价指标（杀灭芽孢为灭菌标准）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1805","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"杀灭细菌芽孢的方法是？","options":["低温冷藏","紫外线照射","75%酒精浸泡","高压蒸汽灭菌法"],"answer":3,"explanation":"高压蒸汽灭菌（121℃、20分钟）可杀灭芽孢，是效果最可靠的灭菌法。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1806","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌荚膜的功能是？","options":["抗吞噬作用","细菌运动","细菌繁殖","产生毒素"],"answer":0,"explanation":"荚膜有抗吞噬、抗干燥等作用，与细菌侵袭力有关。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1807","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌鞭毛的功能是？","options":["黏附","抗吞噬","抵抗干燥","运动"],"answer":3,"explanation":"鞭毛是细菌的运动器官，有鞭毛的细菌可运动。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1808","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌菌毛的功能是？","options":["抗吞噬","运动","黏附（普通菌毛）与遗传物质传递（性菌毛）","产生毒素"],"answer":2,"explanation":"普通菌毛介导细菌对黏膜的黏附（与致病有关），性菌毛传递质粒。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1809","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌的遗传物质包括？","options":["染色体和质粒","只有染色体","只有质粒","核糖体"],"answer":0,"explanation":"细菌基因组包括染色体DNA和质粒（染色体外遗传物质，与耐药性传递有关）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1810","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"质粒的功能是？","options":["细菌染色","细菌运动","细菌呼吸","携带耐药基因等染色体外遗传信息"],"answer":3,"explanation":"质粒是细菌染色体外环状DNA，可携带耐药基因、毒力基因并经性菌毛传递。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1811","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"紫外线杀菌的机制是？","options":["破坏细胞膜","破坏细胞壁","干扰细菌DNA复制","抑制蛋白质合成"],"answer":2,"explanation":"紫外线使DNA同链相邻嘧啶形成二聚体，干扰复制，用于空气和物体表面消毒。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1812","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高压蒸汽灭菌的条件是？","options":["100℃、10分钟","121℃、15-30分钟","80℃、30分钟","60℃、1小时"],"answer":1,"explanation":"121℃维持15-30分钟可杀灭包括芽孢在内的一切微生物。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1813","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"巴氏消毒法用于？","options":["牛奶和酒类消毒","手术器械灭菌","空气消毒","皮肤消毒"],"answer":0,"explanation":"巴氏消毒（61-62℃30分钟或71.7℃15-30秒）用于牛奶、酒类等不耐高温物品消毒。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1814","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"75%乙醇的杀菌机制是？","options":["使菌体蛋白质变性凝固","氧化细菌酶类","破坏细胞壁","抑制DNA复制"],"answer":0,"explanation":"乙醇使蛋白质变性凝固，浓度过高（95%）反而因表面蛋白凝固形成保护膜而杀菌力下降。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1815","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常菌群的作用不包括？","options":["引起自身免疫病","生物拮抗","营养作用","免疫促进"],"answer":0,"explanation":"正常菌群有生物拮抗、营养（合成维生素）、免疫促进等作用，不引起自身免疫病。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1816","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"条件致病菌致病的条件不包括？","options":["细菌毒力显著增强（外源性强毒株）","机体免疫功能低下","菌群失调","定位转移"],"answer":0,"explanation":"条件致病菌在免疫低下、菌群失调、寄居部位改变时致病；其本身毒力通常不强。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1817","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"医院感染最常见的病原体是？","options":["真菌","病毒","细菌（多为条件致病菌）","寄生虫"],"answer":2,"explanation":"医院感染以细菌为主，多为耐药的条件致病菌（如铜绿假单胞菌、金黄色葡萄球菌）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1818","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"金黄色葡萄球菌的致病物质不包括？","options":["血浆凝固酶","肠毒素","外毒素（多种）","内毒素"],"answer":2,"explanation":"金黄色葡萄球菌产生多种外毒素和酶（凝固酶等），不含内毒素（内毒素为革兰阴性菌所有）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1819","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"化脓性感染最常见的病原菌是？","options":["结核分枝杆菌","大肠埃希菌","金黄色葡萄球菌","霍乱弧菌"],"answer":2,"explanation":"金黄色葡萄球菌是化脓性感染最常见的病原菌，产生血浆凝固酶使感染局限化。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1820","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"链球菌感染后引起的超敏反应性疾病是？","options":["伤寒","风湿热和急性肾小球肾炎","破伤风","白喉"],"answer":1,"explanation":"A群链球菌感染后可发生风湿热、急性肾小球肾炎等Ⅲ型（或Ⅱ型）超敏反应性疾病。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1821","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗O试验（ASO）用于辅助诊断？","options":["梅毒","伤寒","结核病","风湿热"],"answer":3,"explanation":"ASO试验检测链球菌溶血素O的抗体，滴度升高提示链球菌感染，辅助诊断风湿热。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1822","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脑膜炎奈瑟菌的传播途径是？","options":["粪-口传播","呼吸道飞沫传播","血液传播","接触传播"],"answer":1,"explanation":"脑膜炎奈瑟菌经呼吸道飞沫传播，引起流行性脑脊髓膜炎（流脑）。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1823","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"伤寒的病原体是？","options":["大肠埃希菌","志贺菌","霍乱弧菌","伤寒沙门菌"],"answer":3,"explanation":"伤寒由伤寒沙门菌引起，经粪-口传播，典型表现为持续发热、相对缓脉、玫瑰疹。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1824","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"志贺菌引起？","options":["伤寒","细菌性痢疾","霍乱","食物中毒（沙门菌型）"],"answer":1,"explanation":"志贺菌（痢疾杆菌）引起细菌性痢疾，表现为发热、腹痛、腹泻、黏液脓血便、里急后重。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1825","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"霍乱弧菌的致病物质主要是？","options":["荚膜","内毒素","霍乱肠毒素","血浆凝固酶"],"answer":2,"explanation":"霍乱肠毒素激活腺苷酸环化酶，使肠液大量分泌，引起剧烈水样腹泻。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1826","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"霍乱的典型大便性状是？","options":["米泔水样便","黏液脓血便","柏油样便","果酱样便"],"answer":0,"explanation":"霍乱弧菌肠毒素致大量肠液分泌，排出米泔水样便，可致严重脱水。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1827","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核分枝杆菌的染色特点是？","options":["革兰染色阴性","革兰染色阳性","抗酸染色阳性","瑞氏染色阳性"],"answer":2,"explanation":"结核分枝杆菌细胞壁含大量脂质（分枝菌酸），抗酸染色呈红色阳性。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1828","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核分枝杆菌的致病物质主要是？","options":["菌体成分（脂质等）引发的Ⅳ型超敏反应","外毒素","内毒素","侵袭性酶"],"answer":0,"explanation":"结核杆菌不产生外毒素和内毒素，其致病与菌体脂质等成分引发的免疫病理（Ⅳ型超敏反应）有关。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1829","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核菌素试验（PPD）的原理是？","options":["Ⅳ型超敏反应（迟发型）","Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅲ型超敏反应"],"answer":0,"explanation":"PPD试验检测机体对结核杆菌的细胞免疫（Ⅳ型超敏反应），48-72小时观察结果。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1830","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风梭菌的感染条件是？","options":["呼吸道","浅表清洁伤口","深部厌氧伤口","消化道"],"answer":2,"explanation":"破伤风梭菌为厌氧菌，深部窄伤口（缺氧环境）易感染，产生痉挛毒素。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1831","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风痉挛毒素的作用是？","options":["阻断抑制性神经递质释放，引起骨骼肌强直性痉挛","破坏红细胞","损伤心肌","抑制呼吸中枢代谢"],"answer":0,"explanation":"痉挛毒素阻断脊髓抑制性中间神经元，使伸肌与屈肌同时强直收缩，出现牙关紧闭、角弓反张。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1832","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"产气荚膜梭菌引起？","options":["破伤风","气性坏疽","肉毒中毒","白喉"],"answer":1,"explanation":"产气荚膜梭菌产生多种毒素和酶，引起气性坏疽（组织气肿、坏死）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1833","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肉毒梭菌的致病物质是？","options":["侵袭性酶","内毒素","肠毒素","肉毒毒素（最强的神经外毒素）"],"answer":3,"explanation":"肉毒毒素是已知最强的神经毒素，阻断胆碱能神经末梢释放乙酰胆碱，引起肌肉弛缓性麻痹。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1834","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"白喉杆菌的致病物质是？","options":["白喉外毒素","内毒素","荚膜","芽孢"],"answer":0,"explanation":"白喉外毒素抑制细胞蛋白质合成，引起心肌和神经损害，局部形成假膜。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1835","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"白喉外毒素的作用机制是？","options":["抑制细胞蛋白质合成","破坏细胞膜","抑制DNA复制","激活腺苷酸环化酶"],"answer":0,"explanation":"白喉外毒素使延伸因子2失活，阻断细胞蛋白质合成，致心肌炎和周围神经麻痹。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1836","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"铜绿假单胞菌的特点是？","options":["对青霉素高度敏感","天然耐药性强，为医院感染重要病原菌","只引起肠道感染","不产生色素"],"answer":1,"explanation":"铜绿假单胞菌（绿脓杆菌）天然耐药性强，产生绿色色素，是烧伤、囊性纤维化等医院感染的重要病原菌。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1837","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"幽门螺杆菌与下列哪种疾病密切相关？","options":["慢性胃炎和消化性溃疡","溃疡性结肠炎","急性胰腺炎","病毒性肝炎"],"answer":0,"explanation":"幽门螺杆菌是慢性胃炎、消化性溃疡的重要致病因子，与胃癌发生相关。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1838","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"支原体的特点是？","options":["只能寄生于活细胞内","有细胞壁","对青霉素敏感","无细胞壁，对青霉素不敏感"],"answer":3,"explanation":"支原体无细胞壁（是最小的原核细胞型微生物），青霉素类（作用于细胞壁）无效，用大环内酯类。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1839","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"衣原体的特点是？","options":["无细胞壁","可在人工培养基生长","严格细胞内寄生，有独特发育周期","为病毒的一种"],"answer":2,"explanation":"衣原体严格细胞内寄生，有原体和网状体（始体）发育周期。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1840","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"立克次体的传播媒介是？","options":["飞沫","节肢动物（虱、蚤、蜱等）","水源","食物"],"answer":1,"explanation":"立克次体经虱、蚤、蜱、螨等节肢动物叮咬传播，引起斑疹伤寒等。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1841","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"螺旋体中引起梅毒的病原体是？","options":["梅毒螺旋体（苍白密螺旋体）","钩端螺旋体","回归热螺旋体","伯氏疏螺旋体"],"answer":0,"explanation":"梅毒由梅毒螺旋体引起，经性接触和垂直传播，青霉素为首选治疗。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1842","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"钩端螺旋体病的主要传染源是？","options":["患者","鼠类和猪","蚊虫","家禽"],"answer":1,"explanation":"钩体病为人畜共患病，鼠类和猪是主要传染源，经疫水接触传播。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1843","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒的基本结构是？","options":["细胞器和细胞核","细胞膜和细胞质","细胞壁和核糖体","核心（核酸）和衣壳（蛋白质）"],"answer":3,"explanation":"病毒为非细胞型微生物，由核酸核心和蛋白质衣壳组成，部分有包膜。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1844","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒的增殖方式是？","options":["孢子生殖","二分裂","以核酸为模板进行复制","出芽生殖"],"answer":2,"explanation":"病毒缺乏独立代谢系统，必须以自身核酸为模板、利用宿主细胞进行复制增殖。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1845","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"干扰素的抗病毒机制是？","options":["破坏病毒包膜","直接杀灭病毒","阻止病毒吸附","诱导细胞产生抗病毒蛋白，间接抑制病毒"],"answer":3,"explanation":"干扰素刺激细胞合成抗病毒蛋白（如蛋白激酶等），间接抑制病毒复制，不直接杀灭病毒。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1846","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒垂直传播是指？","options":["经飞沫传播","经胎盘或产道由母体传给胎儿","经血液制品传播","经粪-口传播"],"answer":1,"explanation":"垂直传播指病原体经胎盘、产道或哺乳由母亲传给子代，如风疹病毒、乙肝病毒、HIV。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1847","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝病毒的传播途径不包括？","options":["性接触传播","血液传播","母婴传播","呼吸道飞沫"],"answer":3,"explanation":"乙肝经血液、母婴和性接触传播，不经呼吸道飞沫传播。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1848","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝病毒感染确诊最有意义的血清学指标是？","options":["肝功能正常","抗-HBs阳性（单独）","抗-HBc IgG阳性（单独）","HBsAg阳性（伴HBeAg或HBV DNA）"],"answer":3,"explanation":"HBsAg阳性表示乙肝病毒感染；抗-HBs阳性为免疫保护标志（疫苗接种或康复）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1849","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝疫苗接种产生的保护性抗体是？","options":["抗-HBs","抗-HBc","抗-HBe","HBsAg"],"answer":0,"explanation":"接种乙肝疫苗后产生抗-HBs（表面抗体），是中和性保护抗体。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1850","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝病毒属于？","options":["RNA病毒","DNA病毒","逆转录病毒（RNA）","缺陷病毒"],"answer":1,"explanation":"HBV为嗜肝DNA病毒，含部分环状双链DNA。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1851","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"丙肝病毒的特点是？","options":["有高效疫苗","DNA病毒","不易慢性化","RNA病毒，易慢性化"],"answer":3,"explanation":"HCV为RNA病毒，感染易慢性化（约50-85%），目前尚无疫苗，现可治愈（直接抗病毒药物）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1852","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"艾滋病的病原体是？","options":["人类免疫缺陷病毒（HIV）","人类T细胞白血病病毒","EB病毒","巨细胞病毒"],"answer":0,"explanation":"HIV为逆转录RNA病毒，主要破坏CD4+T淋巴细胞。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1853","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"HIV主要侵犯的细胞是？","options":["血小板","B淋巴细胞","红细胞","CD4+T淋巴细胞"],"answer":3,"explanation":"HIV通过gp120与CD4分子结合，感染并破坏CD4+T细胞，致免疫功能缺陷。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1854","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"艾滋病的传播途径不包括？","options":["母婴传播","性接触","血液传播","日常生活接触（握手、共餐）"],"answer":3,"explanation":"HIV经性、血液、母婴三种途径传播，日常接触不传播。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1855","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"HIV感染确诊常用的检查是？","options":["初筛ELISA","蛋白印迹试验（确认试验）","血常规","CD4计数"],"answer":1,"explanation":"HIV感染先经ELISA初筛，阳性者用蛋白印迹（Western blot）确认。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1856","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"狂犬病毒的传染源主要是？","options":["患者","患病犬、猫等动物","蚊虫","鼠类"],"answer":1,"explanation":"狂犬病的主要传染源是病犬，其次为猫等，经咬伤传播，发病后病死率近100%。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1857","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"狂犬病伤口的正确处理是？","options":["简单包扎","立即用肥皂水反复冲洗并接种疫苗","热敷伤口","挤压伤口"],"answer":1,"explanation":"被犬咬伤后立即用肥皂水和流水交替冲洗15分钟以上，消毒，并按程序接种狂犬疫苗，必要时用免疫球蛋白。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1858","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流感病毒最易变异的结构是？","options":["核蛋白","血凝素（HA）和神经氨酸酶（NA）","基质蛋白","RNA聚合酶"],"answer":1,"explanation":"HA和NA为流感病毒表面抗原，易发生变异（抗原漂移和转变），是流感反复流行的原因。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1859","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流感病毒的传播途径是？","options":["呼吸道飞沫","粪-口","血液","虫媒"],"answer":0,"explanation":"流感经呼吸道飞沫传播，冬春季流行，甲型易引起大流行。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1860","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"麻疹的典型表现是？","options":["发热当天出疹","发热3-4天后出疹，口腔麻疹黏膜斑（柯氏斑）","无发热出疹","出血性皮疹"],"answer":1,"explanation":"麻疹发热3-4天出疹，出疹前口腔可见麻疹黏膜斑（早期诊断标志），疹间皮肤正常。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1861","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"风疹对孕妇的主要危害是？","options":["引起胎儿先天畸形（先天性风疹综合征）","孕妇重症肺炎","流产不可避免","产后出血"],"answer":0,"explanation":"孕妇妊娠早期感染风疹病毒可致胎儿先天性风疹综合征（先天性心脏病、白内障、耳聋等）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1862","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流行性乙型脑炎的传播媒介是？","options":["血液制品","飞沫","粪-口","蚊虫"],"answer":3,"explanation":"乙脑经蚊虫叮咬传播，夏秋季流行，多见于儿童。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1863","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流行性出血热的病原体是？","options":["黄热病毒","登革病毒","埃博拉病毒","汉坦病毒"],"answer":3,"explanation":"汉坦病毒引起流行性出血热（肾综合征出血热），经鼠类排泄物传播。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1864","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"真菌的基本结构特点是？","options":["非细胞型","原核细胞型","真核细胞型微生物","无细胞结构"],"answer":2,"explanation":"真菌为真核细胞型微生物，有典型细胞核和细胞器，细胞壁不含肽聚糖。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1865","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"皮肤癣菌主要侵犯？","options":["血液","内脏器官","皮肤角质层、毛发和指（趾）甲","神经系统"],"answer":2,"explanation":"皮肤癣菌（毛癣菌等）嗜角质蛋白，引起头癣、体癣、手足癣、甲癣。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1866","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"白色念珠菌的特点是？","options":["条件致病性真菌，正常存在于口腔、肠道等","强致病性真菌","只存在于土壤","为细菌的一种"],"answer":0,"explanation":"白色念珠菌为人体正常菌群，免疫低下、菌群失调时致病（鹅口疮、阴道炎等）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1867","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"新型隐球菌感染易侵犯？","options":["心脏","中枢神经系统","关节","甲状腺"],"answer":1,"explanation":"新型隐球菌经呼吸道吸入，易侵犯中枢神经系统引起隐球菌脑膜炎，脑脊液墨汁染色可见荚膜。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1868","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗生素相关性伪膜性肠炎的病原体是？","options":["伤寒沙门菌","金黄色葡萄球菌","霍乱弧菌","艰难梭菌"],"answer":3,"explanation":"长期大量使用广谱抗生素致菌群失调，艰难梭菌过度繁殖引起伪膜性肠炎。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1869","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗原的基本特性是？","options":["免疫原性和反应原性","只有免疫原性","只有反应原性","只有毒性"],"answer":0,"explanation":"完全抗原既有免疫原性（刺激机体产生免疫应答）又有反应原性（与产物特异性结合）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1870","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"半抗原的特点是？","options":["只有毒性","既有免疫原性又有反应原性","无任何抗原性","只有反应原性而无免疫原性"],"answer":3,"explanation":"半抗原（如青霉素降解物）能与抗体结合但单独不能刺激免疫应答，与载体蛋白结合后成为完全抗原。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1871","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗体（免疫球蛋白）的产生细胞是？","options":["T淋巴细胞","浆细胞（效应B细胞）","巨噬细胞","NK细胞"],"answer":1,"explanation":"B细胞受抗原刺激分化为浆细胞，由浆细胞合成并分泌抗体。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1872","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"免疫球蛋白中分子量最大的是？","options":["IgE","IgG","IgA","IgM"],"answer":3,"explanation":"IgM为五聚体，分子量最大，是个体发育中最早合成的抗体，也是感染早期出现的抗体。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1873","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"能通过胎盘的免疫球蛋白是？","options":["IgE","IgM","IgA","IgG"],"answer":3,"explanation":"IgG是唯一能通过胎盘的抗体，赋予新生儿被动免疫保护。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1874","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"参与Ⅰ型超敏反应的抗体是？","options":["IgG","IgE","IgM","IgA"],"answer":1,"explanation":"IgE与肥大细胞、嗜碱性粒细胞结合，再次接触变应原时释放组胺等介质，引起Ⅰ型超敏反应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1875","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅰ型超敏反应的特点是？","options":["以组织损伤为主","发生快、以功能性紊乱为主、无明显组织损伤","发生缓慢","由IgG介导"],"answer":1,"explanation":"Ⅰ型（速发型）超敏反应发生快，主要引起毛细血管扩张、通透性增加、平滑肌收缩等功能紊乱。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1876","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素过敏性休克属于？","options":["Ⅲ型超敏反应","Ⅱ型超敏反应","Ⅰ型超敏反应","Ⅳ型超敏反应"],"answer":2,"explanation":"青霉素过敏性休克由IgE介导，属Ⅰ型（速发型）超敏反应。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1877","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅱ型超敏反应的特点是？","options":["抗体（IgG、IgM）与细胞表面抗原结合，破坏靶细胞","由IgE介导","以肉芽肿形成为特征","发生最慢"],"answer":0,"explanation":"Ⅱ型（细胞毒型）超敏反应由IgG、IgM与靶细胞抗原结合，经补体或吞噬细胞破坏靶细胞（如输血反应）。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1878","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"新生儿溶血症属于？","options":["Ⅲ型超敏反应","Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅳ型超敏反应"],"answer":2,"explanation":"Rh或ABO血型不合的新生儿溶血症由母体抗体破坏胎儿红细胞，属Ⅱ型超敏反应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1879","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅲ型超敏反应的典型代表是？","options":["免疫复合物型（如链球菌感染后肾小球肾炎）","过敏性休克","输血反应","接触性皮炎"],"answer":0,"explanation":"Ⅲ型超敏反应由可溶性免疫复合物沉积引起炎症（如风湿热、链球菌感染后肾炎）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1880","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅳ型超敏反应的特点是？","options":["发生最快","由抗体介导","由T细胞介导，发生缓慢（24-72小时）","由补体介导"],"answer":2,"explanation":"Ⅳ型（迟发型）超敏反应由致敏T细胞介导，如结核菌素试验、接触性皮炎、移植排斥。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1881","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核菌素试验阳性反应的机制是？","options":["Ⅲ型超敏反应","Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅳ型超敏反应"],"answer":3,"explanation":"PPD试验为典型的Ⅳ型（迟发型）超敏反应，48-72小时出现红肿硬结。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1882","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"免疫系统的功能不包括？","options":["产生消化酶","免疫防御","免疫自稳","免疫监视"],"answer":0,"explanation":"免疫系统有防御（抗感染）、自稳（清除衰老细胞）、监视（清除突变细胞）三大功能。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1883","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中枢免疫器官包括？","options":["肝脏和脾脏","脾脏和淋巴结","扁桃体和阑尾","骨髓和胸腺"],"answer":3,"explanation":"中枢免疫器官（骨髓、胸腺）是免疫细胞发生、分化成熟的场所；外周免疫器官（脾、淋巴结等）是免疫应答场所。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1884","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"T淋巴细胞成熟的场所是？","options":["胸腺","骨髓","脾脏","淋巴结"],"answer":0,"explanation":"T细胞在胸腺内发育成熟；B细胞在骨髓（哺乳类）成熟。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1885","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"B淋巴细胞的功能主要是？","options":["产生抗体介导体液免疫","直接杀伤靶细胞","吞噬病原体","释放淋巴因子介导细胞免疫"],"answer":0,"explanation":"B细胞受抗原刺激增殖分化为浆细胞，产生抗体，介导体液免疫。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1886","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"NK细胞的特点是？","options":["产生抗体","需抗体协助才能活化","只杀伤病毒","无需抗原预先致敏即可杀伤靶细胞"],"answer":3,"explanation":"NK细胞（自然杀伤细胞）无需预先致敏、无MHC限制性，直接杀伤肿瘤细胞和病毒感染细胞。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1887","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"补体的生物学作用不包括？","options":["调理吞噬","溶解细胞","直接产生抗体","炎症介质作用"],"answer":2,"explanation":"补体经激活后可溶解细胞、调理吞噬、引起炎症、免疫黏附等，不产生抗体。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1888","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"经典途径激活补体的主要物质是？","options":["细菌脂多糖","抗原抗体复合物（IgG、IgM）","凝集素","备解素"],"answer":1,"explanation":"经典途径由抗原抗体复合物（IgG1-3、IgM）启动；脂多糖激活旁路途径。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1889","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"疫苗的基本原理是？","options":["补充免疫细胞","直接提供抗体","杀灭病原体","用抗原刺激机体产生特异性免疫（主动免疫）"],"answer":3,"explanation":"疫苗（抗原）接种后刺激机体主动产生抗体和细胞免疫，获得特异性免疫保护。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1890","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"人工主动免疫与人工被动免疫的主要区别是？","options":["前者生效快","前者接种抗原、产生慢而持久；后者注射抗体、生效快而短暂","后者持久","无区别"],"answer":1,"explanation":"人工主动免疫（疫苗）起效慢、维持久；人工被动免疫（免疫球蛋白、抗毒素）起效快、维持短。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1891","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝免疫球蛋白属于？","options":["抗生素","人工主动免疫制剂","类毒素","人工被动免疫制剂"],"answer":3,"explanation":"乙肝免疫球蛋白是含高效价抗-HBs的血浆制品，属被动免疫，用于暴露后应急保护。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1892","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"卡介苗（BCG）属于？","options":["灭活疫苗","减毒活疫苗","类毒素","抗毒素"],"answer":1,"explanation":"卡介苗为牛型结核杆菌减毒活疫苗，用于预防结核病。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1893","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风抗毒素（TAT）的作用机制是？","options":["中和游离的外毒素","杀灭破伤风杆菌","抑制细菌繁殖","溶解细菌细胞壁"],"answer":0,"explanation":"TAT为被动免疫制剂，中和游离外毒素，对已与神经组织结合的毒素无效。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1894","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"免疫耐受是指？","options":["免疫功能低下","对特定抗原的特异性无应答状态","对所有抗原无应答","过敏反应"],"answer":1,"explanation":"免疫耐受是免疫系统对特定抗原不产生应答，具有抗原特异性，对自身抗原耐受是防止自身免疫病的关键。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1895","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"自身免疫病的发病机制主要是？","options":["补体过多","外源性抗原过多","免疫缺陷","对自身抗原的免疫耐受被打破"],"answer":3,"explanation":"自身免疫病是机体对自身组织产生免疫应答（耐受破坏），如系统性红斑狼疮、类风湿关节炎。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1896","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"超急性排斥反应的机制是？","options":["免疫缺陷","T细胞介导的迟发反应","免疫耐受","受者体内预存抗体与移植器官抗原结合（Ⅱ型超敏反应样）"],"answer":3,"explanation":"超急性排斥在移植后数分钟至数小时发生，由受者预存抗体（如抗血型抗体）引起。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1897","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"器官移植时最重要的组织配型抗原是？","options":["补体","血型抗原","人类白细胞抗原（HLA）","免疫球蛋白"],"answer":2,"explanation":"HLA（MHC）配型是器官移植成功的关键，HLA差异越大排斥反应越强。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1898","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肿瘤免疫逃逸的机制不包括？","options":["肿瘤细胞高表达MHC分子","肿瘤抗原表达下调","分泌免疫抑制因子","诱导免疫耐受"],"answer":0,"explanation":"肿瘤细胞常下调MHC表达以逃避免疫识别，而非高表达。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1899","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"免疫缺陷病的特点是？","options":["只表现为过敏","反复感染、易发生恶性肿瘤","只表现为自身免疫","无感染倾向"],"answer":1,"explanation":"免疫缺陷（如HIV、原发性免疫缺陷）表现为反复感染、易肿瘤、可伴自身免疫。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1900","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人腋测法体温参考范围是？","options":["35.0-36.0℃","36.0-37.0℃","37.0-38.0℃","36.5-37.7℃"],"answer":1,"explanation":"腋测法正常为36.0-37.0℃；口测法36.3-37.2℃；肛测法36.5-37.7℃。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1901","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"发热最常见的病因是？","options":["内分泌代谢障碍","无菌性坏死物质吸收","抗原抗体反应","感染性发热"],"answer":3,"explanation":"感染性发热最常见，由各种病原体感染引起。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1902","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"弛张热的特点是？","options":["体温骤升骤降、高热期与无热期交替","体温恒定维持在39-40℃以上","体温常在39℃以上，24小时波动范围超过2℃","体温逐渐上升又逐渐下降"],"answer":2,"explanation":"弛张热常见于败血症、风湿热、重症肺结核等；稽留热24小时波动不超过1℃。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1903","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"间歇热的特点是？","options":["高热期与无热期交替出现","体温恒定","体温渐升渐降","低热持续"],"answer":0,"explanation":"间歇热见于疟疾、急性肾盂肾炎等，高热与无热反复交替。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1904","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"体温骤升骤降、高热与无热期交替出现，见于？","options":["结核病（长期低热）","大叶性肺炎（稽留热）","疟疾","伤寒（阶梯上升）"],"answer":2,"explanation":"疟疾发作时寒战高热、大汗后退热，呈间歇热。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1905","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"稽留热常见于？","options":["大叶性肺炎","疟疾","败血症","风湿热"],"answer":0,"explanation":"稽留热体温恒定于39-40℃以上，24小时波动<1℃，见于大叶性肺炎、伤寒高热期。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1906","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心源性水肿首先出现的部位是？","options":["身体下垂部位（下肢）","眼睑和面部","腹部","胸腔"],"answer":0,"explanation":"心源性水肿从下垂部位开始（仰卧者先骶部）；肾性水肿先从眼睑、面部开始。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1907","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肾性水肿的特点是？","options":["腹水为主","下肢下垂部位先肿","晨起眼睑和颜面水肿","非凹陷性水肿"],"answer":2,"explanation":"肾性水肿组织疏松部位先肿，晨起眼睑颜面水肿明显。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1908","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"干性咳嗽（无痰）常见于？","options":["肺脓肿","慢性支气管炎","支气管扩张","急性咽喉炎、胸膜炎"],"answer":3,"explanation":"干咳见于咽喉炎、胸膜炎、肺癌早期等；湿咳见于慢支、支扩、肺脓肿。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1909","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"咳痰呈铁锈色提示？","options":["肺炎链球菌肺炎","肺结核","肺脓肿","支气管扩张"],"answer":0,"explanation":"铁锈色痰是肺炎链球菌（肺炎球菌）肺炎的典型表现。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1910","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"咳大量脓臭痰提示？","options":["心源性哮喘","肺炎链球菌肺炎","干性胸膜炎","肺脓肿（厌氧菌感染）"],"answer":3,"explanation":"肺脓肿痰量大、静置分层，厌氧菌感染时痰有恶臭。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1911","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"痰液静置后分层（上层泡沫、中层浆液、下层脓块）见于？","options":["肺癌","大叶性肺炎","支气管扩张","哮喘"],"answer":2,"explanation":"支气管扩张和肺脓肿患者痰量多，静置后分三层。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1912","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"咯血与呕血的鉴别要点不包括？","options":["咯血前有恶心而呕血前有恶心（相同点）","咯血颜色鲜红、呕血暗红","咯血混有痰、呕血混有胃内容物","咯血pH碱性、呕血酸性"],"answer":0,"explanation":"咯血与呕血前均可有恶心，不是鉴别点；其余均为鉴别要点。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1913","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呼吸困难表现为吸气费力、三凹征，属于？","options":["呼气性呼吸困难","吸气性呼吸困难","混合性呼吸困难","心源性呼吸困难"],"answer":1,"explanation":"吸气性呼吸困难见于喉头水肿、气管异物等大气道梗阻，出现胸骨上窝、锁骨上窝、肋间隙凹陷（三凹征）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1914","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呼气性呼吸困难常见于？","options":["喉头水肿","支气管哮喘和阻塞性肺气肿","气管异物","大量胸腔积液"],"answer":1,"explanation":"呼气性呼吸困难因小气道狭窄、肺弹性减弱，呼气费力延长，见于哮喘、肺气肿。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1915","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Kussmaul呼吸（深大呼吸）常见于？","options":["支气管哮喘","糖尿病酮症酸中毒","脑出血","肺水肿"],"answer":1,"explanation":"代谢性酸中毒时呼吸深大（酸中毒大呼吸），代偿性排出CO2。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1916","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"潮式呼吸（Cheyne-Stokes呼吸）的特点是？","options":["呼吸深大规则","呼吸由浅慢逐渐深快再变浅慢，暂停后周而复始","呼吸浅快","呼吸突然停止"],"answer":1,"explanation":"潮式呼吸见于中枢神经系统疾病和心衰、尿毒症等，提示呼吸中枢兴奋性降低。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1917","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胸痛伴呼吸困难、气管向健侧移位，提示？","options":["大量气胸","心绞痛","肋间神经痛","肺结核"],"answer":0,"explanation":"大量气胸时患侧胸廓饱满、气管移向健侧，伴呼吸困难和胸痛。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1918","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心绞痛胸痛的特点是？","options":["深呼吸加重","刺痛持续数天","胸骨后压榨性疼痛，含服硝酸甘油可缓解","与体位有关"],"answer":2,"explanation":"典型心绞痛为胸骨后压榨性闷痛，持续3-5分钟，休息或含服硝酸甘油缓解。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1919","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胸痛伴吞咽困难提示？","options":["气胸","心绞痛","肋软骨炎","食管疾病"],"answer":3,"explanation":"食管疾病（食管炎、食管癌）胸痛常于吞咽时加重，伴吞咽困难。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1920","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"发绀的常见原因是？","options":["血液中碳氧血红蛋白增多（轻度）","血液中还原血红蛋白增多","贫血","白细胞增多"],"answer":1,"explanation":"发绀主要由还原血红蛋白增多（>50g/L）或异常血红蛋白血症引起。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1921","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中心性发绀的特点是？","options":["由局部血流障碍引起","仅肢端发绀、皮肤发凉","加温后消失","全身性发绀，皮肤温暖"],"answer":3,"explanation":"中心性发绀由心肺疾病致动脉血氧饱和度降低，全身分布、皮肤温暖；周围性发绀见于肢端、皮肤凉。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1922","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心悸的常见原因不包括？","options":["贫血","心律失常","甲状腺功能亢进","血糖升高"],"answer":3,"explanation":"心悸见于心律失常、心脏搏动增强（贫血、甲亢、发热）和神经症，与血糖无关。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1923","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"恶心呕吐伴头痛、喷射性呕吐提示？","options":["前庭功能障碍","幽门梗阻","急性胃肠炎","颅内压增高"],"answer":3,"explanation":"喷射性呕吐是颅内压增高的特征表现，呕吐前无恶心先兆。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1924","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呕血伴蜘蛛痣、肝掌，提示？","options":["肝硬化门脉高压","消化性溃疡","急性胃黏膜病变","食管癌"],"answer":0,"explanation":"肝硬化门脉高压致食管胃底静脉曲张破裂出血，伴肝病面容、蜘蛛痣、肝掌。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1925","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性腹泻伴里急后重提示？","options":["结肠肝曲病变","小肠病变","直肠病变（如细菌性痢疾）","胃部病变"],"answer":2,"explanation":"里急后重（便意频繁、排便不尽感）提示直肠刺激，见于菌痢、直肠癌等。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1926","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"溶血性黄疸的特点是？","options":["尿胆红素强阳性","结合胆红素升高为主","血清非结合胆红素升高，尿胆原增加、尿胆红素阴性","大便呈陶土色"],"answer":2,"explanation":"溶血性黄疸大量红细胞破坏，非结合胆红素升高，尿胆原增加而尿胆红素阴性。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1927","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胆汁淤积性黄疸的特点是？","options":["脾大伴溶血","尿胆原明显增加","非结合胆红素升高为主","大便呈陶土色、尿胆红素强阳性"],"answer":3,"explanation":"胆汁淤积（梗阻性）黄疸直接胆红素升高，尿胆红素强阳性、尿胆原减少，大便陶土色。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1928","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝细胞性黄疸的化验特点是？","options":["仅非结合胆红素升高","结合与非结合胆红素均升高，尿胆红素阳性、尿胆原增加","尿胆红素阴性","大便陶土色"],"answer":1,"explanation":"肝细胞性黄疸肝细胞摄取、结合、排泄胆红素均障碍，双相升高。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1929","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"意识障碍由轻到重的顺序是？","options":["昏迷→昏睡→嗜睡","嗜睡→意识模糊→昏睡→昏迷","意识模糊→嗜睡→昏睡","昏睡→意识模糊→昏迷"],"answer":1,"explanation":"意识障碍程度由轻到重：嗜睡、意识模糊、昏睡、昏迷（浅昏迷、深昏迷）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1930","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"浅昏迷与深昏迷的鉴别要点是？","options":["深昏迷对任何刺激均无反应、各种反射消失","浅昏迷无角膜反射","深昏迷仍有吞咽反射","浅昏迷瞳孔散大"],"answer":0,"explanation":"浅昏迷对强烈刺激尚有反应、反射存在；深昏迷对一切刺激无反应、深浅反射消失。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1931","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人安静状态下呼吸频率是？","options":["30-40次/分","8-12次/分","20-30次/分","12-20次/分"],"answer":3,"explanation":"正常成人呼吸12-20次/分，超过24次/分为呼吸过速。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1932","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人安静状态下心率为？","options":["100-120次/分","40-60次/分","60-100次/分","120-140次/分"],"answer":2,"explanation":"正常成人安静心率60-100次/分，>100为心动过速，<60为心动过缓。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1933","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人血压（收缩压/舒张压）为？","options":["80-120/50-80 mmHg","140-159/90-99 mmHg","90-139/60-89 mmHg","150-170/95-105 mmHg"],"answer":2,"explanation":"正常成人血压收缩压90-139mmHg、舒张压60-89mmHg；≥140/90为高血压。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1934","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脉压增大（>40mmHg）常见于？","options":["主动脉瓣关闭不全和甲状腺功能亢进","主动脉瓣狭窄","心包积液","休克"],"answer":0,"explanation":"脉压增大见于主动脉瓣关闭不全、甲亢、动脉硬化等；脉压减小见于心包积液、主动脉瓣狭窄。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1935","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"交替脉提示？","options":["主动脉瓣狭窄","右心衰竭","心包积液","左心衰竭"],"answer":3,"explanation":"交替脉（强弱交替）提示心肌严重损害，是左心衰竭的重要体征。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1936","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"奇脉（吸停脉）常见于？","options":["主动脉瓣关闭不全","左心衰竭","大量心包积液（心包填塞）","高血压"],"answer":2,"explanation":"奇脉指吸气时脉搏明显减弱或消失，见于心包填塞、哮喘重度发作。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1937","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"水冲脉常见于？","options":["主动脉瓣关闭不全","主动脉瓣狭窄","心包积液","二尖瓣狭窄"],"answer":0,"explanation":"水冲脉（脉搏骤起骤落）见于主动脉瓣关闭不全、甲亢、动脉导管未闭等。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1938","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人24小时尿量为？","options":["2000-3000 ml","500-1000 ml","1000-2000 ml","3000-4000 ml"],"answer":2,"explanation":"成人24小时尿量约1000-2000ml；<400ml为少尿，<100ml为无尿，>2500ml为多尿。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1939","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"24小时尿量少于400ml称为？","options":["正常","无尿","多尿","少尿"],"answer":3,"explanation":"少尿<400ml/24h，无尿<100ml/24h，多尿>2500ml/24h。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1940","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血尿伴疼痛（肾绞痛）提示？","options":["急性肾炎","泌尿系结石","泌尿系肿瘤","膀胱炎"],"answer":1,"explanation":"血尿伴剧烈腰痛（肾绞痛）多为结石梗阻；无痛性血尿警惕肿瘤。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1941","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"无痛性肉眼血尿应首先考虑？","options":["肾结核","泌尿系结石","急性膀胱炎","泌尿系肿瘤"],"answer":3,"explanation":"中老年人无痛性全程血尿首先警惕泌尿系肿瘤（如膀胱癌、肾癌）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1942","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"尿频、尿急、尿痛（膀胱刺激征）常见于？","options":["急性肾炎","泌尿系感染","肾病综合征","慢性肾衰"],"answer":1,"explanation":"膀胱刺激征由泌尿系感染（膀胱炎、尿道炎）引起，也可为结石、结核表现。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1943","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"上消化道出血量达多少可出现黑便？","options":["1000 ml","5 ml","50-70 ml","10 ml"],"answer":2,"explanation":"每日出血量>50-70ml出现黑便；>5ml可出现粪便隐血阳性；胃内积血250-300ml可呕血。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1944","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呕血提示胃内积血量至少为？","options":["50 ml","250-300 ml","100 ml","1000 ml"],"answer":1,"explanation":"胃内积血达250-300ml可引起呕血。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1945","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"周围血中网织红细胞增多提示？","options":["骨髓造血功能活跃（如溶血、失血后）","骨髓造血功能衰竭","缺铁未纠正","再生障碍性贫血"],"answer":0,"explanation":"网织红细胞升高提示骨髓红系造血活跃，见于溶血性贫血、急性失血、有效治疗后。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1946","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中性粒细胞增多最常见的原因是？","options":["急性感染（尤其化脓性细菌）","病毒感染","再生障碍性贫血","脾功能亢进"],"answer":0,"explanation":"中性粒细胞增多常见于化脓性细菌感染；病毒感染多致淋巴细胞增多。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1947","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"嗜酸性粒细胞增多常见于？","options":["化脓性感染","过敏性疾病和寄生虫感染","病毒性肝炎","再生障碍性贫血"],"answer":1,"explanation":"嗜酸性粒细胞增多见于过敏（哮喘、荨麻疹）和寄生虫感染（钩虫、血吸虫等）。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1948","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"淋巴细胞增多常见于？","options":["败血症","化脓性感染","寄生虫病","病毒感染（如传染性单核细胞增多症）"],"answer":3,"explanation":"病毒感染时淋巴细胞增多；化脓菌感染时中性粒细胞增多。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1949","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"红细胞沉降率（血沉）增快的原因不包括？","options":["感染、结核、风湿活动","红细胞增多症","恶性肿瘤","组织损伤"],"answer":1,"explanation":"血沉增快见于炎症、结核、风湿、肿瘤、组织损伤等；红细胞增多症血沉减慢。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1950","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人血小板参考范围是？","options":["(300-500)×10⁹/L","(50-100)×10⁹/L","(100-300)×10⁹/L","(10-30)×10⁹/L"],"answer":2,"explanation":"正常血小板计数为(100-300)×10⁹/L，<100×10⁹/L为血小板减少。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1951","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常人血清白蛋白/球蛋白（A/G）比值为？","options":["0.5-1:1","1.5-2.5:1","3-5:1","5-10:1"],"answer":1,"explanation":"血清白蛋白35-55g/L，球蛋白20-30g/L，A/G比值1.5-2.5:1，肝硬化时倒置。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1952","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血清总胆红素正常参考值是？","options":["1.7-3.4 μmol/L","34-170 μmol/L","3.4-17.1 μmol/L","50-100 μmol/L"],"answer":2,"explanation":"总胆红素正常3.4-17.1μmol/L，>17.1μmol/L为黄疸（隐性黄疸17.1-34.2）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1953","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"丙氨酸氨基转移酶（ALT）升高最常见于？","options":["骨骼肌损伤","心肌梗死","肝细胞损伤","肾病"],"answer":2,"explanation":"ALT主要存在于肝细胞内，肝细胞损伤时释放入血，是肝损害最敏感指标之一。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1954","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血肌酐升高的主要意义是？","options":["胰腺炎","肝功能减退","心肌损伤","肾小球滤过功能减退"],"answer":3,"explanation":"血肌酐反映肾小球滤过功能，明显升高提示肾功能不全。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1955","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"空腹血糖的正常参考值是？","options":["3.9-6.1 mmol/L","6.1-7.8 mmol/L","7.8-11.1 mmol/L","2.8-3.9 mmol/L"],"answer":0,"explanation":"空腹血糖3.9-6.1mmol/L为正常；≥7.0mmol/L考虑糖尿病（需复查）。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1956","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"诊断糖尿病的空腹血糖标准是？","options":["≥11.1 mmol/L（空腹）","≥6.1 mmol/L","≥7.0 mmol/L","≥5.6 mmol/L"],"answer":2,"explanation":"空腹血糖≥7.0mmol/L或餐后2小时≥11.1mmol/L，或有症状+随机血糖≥11.1mmol/L可诊断糖尿病。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1957","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"口服葡萄糖耐量试验（OGTT）2小时血糖≥多少可诊断糖尿病？","options":["6.1 mmol/L","7.8 mmol/L","11.1 mmol/L","9.0 mmol/L"],"answer":2,"explanation":"OGTT 2小时血糖≥11.1mmol/L可诊断糖尿病；7.8-11.1为糖耐量减低。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1958","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血清钾正常参考值是？","options":["5.5-6.5 mmol/L","2.5-3.5 mmol/L","3.5-5.5 mmol/L","6.5-7.5 mmol/L"],"answer":2,"explanation":"血钾3.5-5.5mmol/L；<3.5为低钾，>5.5为高钾。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1959","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低钾血症最早的心电图表现是？","options":["P波消失","T波高尖","QRS增宽","T波低平、U波增高"],"answer":3,"explanation":"低钾血症心电图早期T波低平、U波出现或增高，重者ST段下移。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1960","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高钾血症最危险的表现是？","options":["四肢麻木","心室颤动、心脏停搏","恶心呕吐","嗜睡"],"answer":1,"explanation":"高钾血症抑制心肌，严重者室颤或停搏，需紧急降钾处理。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1961","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血清钠正常参考值是？","options":["155-165 mmol/L","125-135 mmol/L","145-155 mmol/L","135-145 mmol/L"],"answer":3,"explanation":"血钠135-145mmol/L；<135为低钠血症。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1962","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"动脉血气分析中，pH正常参考范围是？","options":["7.45-7.55","7.25-7.35","7.35-7.45","7.15-7.25"],"answer":2,"explanation":"动脉血pH正常7.35-7.45；<7.35为酸中毒，>7.45为碱中毒。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1963","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅰ型呼吸衰竭的血气特点是？","options":["PaO₂<60mmHg伴PaCO₂>50mmHg","PaO₂<60mmHg，PaCO₂正常或降低","PaO₂正常，PaCO₂升高","PaO₂>60mmHg"],"answer":1,"explanation":"Ⅰ型呼衰为低氧血症型（换气障碍），PaO₂<60mmHg不伴CO₂潴留；Ⅱ型伴PaCO₂>50mmHg。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1964","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅱ型呼吸衰竭的血气诊断标准是？","options":["仅PaCO₂>50mmHg","仅PaO₂<60mmHg","PaO₂<60mmHg且PaCO₂>50mmHg","pH<7.35"],"answer":2,"explanation":"Ⅱ型呼衰为低氧伴高碳酸血症（通气障碍），需同时满足两条标准。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1965","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心电图上反映心房除极的波是？","options":["T波","QRS波群","P波","U波"],"answer":2,"explanation":"P波代表心房除极；QRS代表心室除极；T波代表心室复极。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1966","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心电图上QRS波群代表？","options":["房室传导","心房除极","心室复极","心室除极"],"answer":3,"explanation":"QRS波群反映心室除极电位变化；T波为心室复极。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1967","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常窦性心律的心电图特征不包括？","options":["P-R间期>0.20秒","P波在Ⅰ、Ⅱ、aVF导联直立","频率60-100次/分","P-P间期规则"],"answer":0,"explanation":"正常P-R间期0.12-0.20秒，>0.20秒为一度房室传导阻滞。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1968","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死心电图最有诊断价值的表现是？","options":["窦性心动过速","ST段压低","T波倒置","ST段弓背向上抬高伴病理性Q波"],"answer":3,"explanation":"ST段弓背向上抬高、病理性Q波、T波动态演变是急性心梗的特征性心电图改变。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1969","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死早期（数小时内）最常见的心律失常是？","options":["心房颤动","房室传导阻滞","室性早搏和室性心动过速","窦性心动过缓"],"answer":2,"explanation":"急性心梗早期以室性心律失常（室早、室速）最常见，可发展为室颤。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1970","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心房颤动的心电图特点是？","options":["P-R间期延长","P波消失代之以F波、R-R规则","P波消失，代之以f波，R-R间期绝对不规则","QRS宽大畸形"],"answer":2,"explanation":"房颤心电图：P波消失、f波（350-600次/分）、R-R绝对不齐。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1971","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心室颤动的心电图特点是？","options":["P波消失","QRS-T完全消失，代之以不规则波动","R-R间期规则","ST段抬高"],"answer":1,"explanation":"室颤为最严重心律失常，QRS-T波群消失，出现不规则波动，需立即除颤。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1972","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"一度房室传导阻滞的心电图表现是？","options":["P波与QRS完全无关","部分P波后无QRS波","P-R间期>0.20秒，P波后均有QRS波","心室率40次/分"],"answer":2,"explanation":"一度房室传导阻滞仅有P-R间期延长（>0.20秒），无QRS脱落。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1973","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"三度房室传导阻滞的心电图特点是？","options":["部分P波后无QRS","P-R间期逐渐延长","P波与QRS波群完全无关，心房率>心室率","P-R间期固定延长"],"answer":2,"explanation":"三度（完全性）房室传导阻滞心房心室各自独立，P波与QRS无关，需起搏治疗。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1974","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"室性早搏的心电图特点是？","options":["P-R间期延长","提前出现窄QRS波前有P波","提前出现的宽大畸形QRS波，其前无P波","R-R间期绝对规则"],"answer":2,"explanation":"室性早搏：提前宽大畸形QRS、T波反向、代偿间歇完全。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1975","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心房扑动的心电图特征是？","options":["P-R延长","f波","P波消失代之以锯齿状F波（250-350次/分）","QRS畸形"],"answer":2,"explanation":"房扑见锯齿状F波，房室传导常呈2:1或4:1。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1976","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"左心室肥大的心电图表现是？","options":["RV₅+SV₁≥4.0mV（男）","RV₁+SV₅≥4.0mV","P波高尖","病理性Q波"],"answer":0,"explanation":"左室肥大：RV₅+SV₁≥4.0mV（男）或≥3.5mV（女），伴电轴左偏。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1977","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"右心室肥大的心电图表现是？","options":["RV₅+SV₁≥4.0mV","RV₁+SV₅≥1.2mV，电轴右偏","P波增宽","T波高尖"],"answer":1,"explanation":"右室肥大：RV₁增高、RV₁+SV₅≥1.2mV、电轴右偏、V₁导联R/S>1。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1978","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"二尖瓣型P波提示？","options":["左心房肥大","右心房肥大","左心室肥大","右心室肥大"],"answer":0,"explanation":"二尖瓣型P波（P波增宽>0.12秒、双峰）提示左房肥大，见于二尖瓣狭窄。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1979","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺型P波提示？","options":["心包积液","左心房肥大","右心室肥大","右心房肥大"],"answer":3,"explanation":"肺型P波（P波高尖≥0.25mV，Ⅱ、Ⅲ、aVF明显）提示右房肥大，见于慢性肺心病。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1980","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"X线检查中，胸腔积液量达多少可显示肋膈角变钝？","options":["约200-300 ml","50 ml","1000 ml","1500 ml"],"answer":0,"explanation":"胸腔积液200-300ml时X线显示肋膈角变钝；中等量积液见外高内低弧形影。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1981","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"大量胸腔积液的X线表现是？","options":["肺门影缩小","纵隔向患侧移位","双肺透亮度增加","患侧密度增高、纵隔向健侧移位"],"answer":3,"explanation":"大量胸腔积液推挤纵隔向健侧移位；肺不张时纵隔向患侧移位。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1982","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阻塞性肺气肿的X线表现是？","options":["双肺透亮度增加、膈肌低平","双肺透亮度降低","膈肌抬高","纵隔向患侧移位"],"answer":0,"explanation":"肺气肿时肺含气增多，透亮度增加、膈肌下降、肋间隙增宽、心影狭长。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1983","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹部X线平片见膈下游离气体提示？","options":["肠梗阻","胃肠道穿孔","急性胰腺炎","肝破裂（无空腔脏器损伤）"],"answer":1,"explanation":"膈下游离气体是胃肠道穿孔的特异性X线征象。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1984","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肠梗阻典型的X线表现是？","options":["双膈下积气","膈下游离气体","膈肌抬高","肠管扩张积气伴多个阶梯状气液平面"],"answer":3,"explanation":"肠梗阻X线见肠管扩张、积气积液，立位见多发阶梯状液平面。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1985","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性胰腺炎诊断最有价值的血清学检查是？","options":["血肌酐","血淀粉酶和脂肪酶","血钙（早期诊断价值有限）","血常规"],"answer":1,"explanation":"血淀粉酶（发病2-12小时升高）和脂肪酶（更特异）是急性胰腺炎主要诊断指标。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1986","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性胰腺炎时血淀粉酶升高的时间是？","options":["发病后3天","发病后1周","发病后立即","发病后2-12小时开始升高"],"answer":3,"explanation":"血淀粉酶发病2-12小时升高，24-48小时达高峰，持续3-5天。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1987","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"超声检查对下列哪种疾病最有诊断价值？","options":["胆结石","胃癌","结肠癌","胰腺癌（早期）"],"answer":0,"explanation":"超声对胆囊结石诊断准确率>95%，是首选检查。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1988","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中枢性面瘫与周围性面瘫的鉴别要点是？","options":["无区别","中枢性面瘫额纹消失","周围性面瘫只累及上面部","中枢性面瘫只累及下面部（额纹存在）"],"answer":3,"explanation":"中枢性面瘫（皮质脑干束损害）仅下面部瘫痪、额纹保留；周围性面瘫（面神经损害）同侧全部面肌瘫痪、额纹消失。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1989","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脑膜刺激征包括？","options":["肌张力增高","Babinski征、Oppenheim征","腱反射亢进","颈强直、Kernig征、Brudzinski征"],"answer":3,"explanation":"脑膜刺激征三项：颈强直、克氏征、布氏征，见于脑膜炎、蛛网膜下腔出血。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1990","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Babinski征（巴宾斯基征）阳性提示？","options":["小脑病变","下运动神经元损害","锥体束（上运动神经元）损害","周围神经病变"],"answer":2,"explanation":"Babinski征阳性为锥体束损害的重要体征，正常2岁以下婴儿可为阳性。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1991","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肌张力呈铅管样强直伴静止性震颤提示？","options":["帕金森病","小脑病变","周围神经病","癫痫"],"answer":0,"explanation":"帕金森病表现为静止性震颤、铅管样（齿轮样）肌张力增高、运动迟缓。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1992","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"共济运动检查中指鼻试验阳性提示？","options":["小脑病变或深感觉障碍","锥体束损害","周围神经损伤","大脑皮层病变"],"answer":0,"explanation":"指鼻试验、跟膝胫试验、快复轮替动作等检查共济运动，阳性提示小脑或深感觉病变。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1993","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"偏瘫的病变部位在？","options":["同侧小脑","对侧大脑半球（皮质运动区或内囊）","同侧脊髓","对侧小脑"],"answer":1,"explanation":"大脑半球病变引起对侧偏瘫（交叉支配），内囊损害致对侧偏瘫、偏身感觉障碍、偏盲（三偏征）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1994","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"三偏征（偏瘫、偏身感觉障碍、偏盲）提示病变在？","options":["脑干","内囊","小脑","脊髓"],"answer":1,"explanation":"内囊区病变（如脑出血）典型表现为三偏征。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1995","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腰椎穿刺脑脊液检查的禁忌证是？","options":["蛛网膜下腔出血","脑膜炎","颅内压显著增高（脑疝风险）","多发性硬化"],"answer":2,"explanation":"颅内压显著增高者腰穿可诱发脑疝，为相对禁忌，需先降颅压。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1996","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常脑脊液压力为？","options":["20-60 mmH₂O","80-180 mmH₂O","200-300 mmH₂O","300-400 mmH₂O"],"answer":1,"explanation":"脑脊液压力侧卧位正常80-180mmH₂O，>200mmH₂O为颅内压增高。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1997","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"化脓性脑膜炎脑脊液特点是？","options":["以淋巴细胞为主","外观清亮、糖正常","外观浑浊、白细胞显著升高（以中性粒细胞为主）、糖明显降低","蛋白正常"],"answer":2,"explanation":"化脑脑脊液浑浊或脓性、压力高、白细胞>1000×10⁶/L（中性为主）、蛋白高、糖低。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1998","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核性脑膜炎脑脊液特点是？","options":["以中性粒细胞为主","外观毛玻璃样、以淋巴细胞为主、糖和氯化物降低、蛋白升高","糖正常","外观脓性"],"answer":1,"explanation":"结脑脑脊液毛玻璃样、静置可有薄膜形成、淋巴细胞为主、蛋白高、糖和氯化物低。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1999","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒性脑炎脑脊液特点是？","options":["糖明显降低","外观清亮、以淋巴细胞为主、糖和氯化物正常","外观脓性","中性粒细胞为主"],"answer":1,"explanation":"病毒性脑炎脑脊液清亮、压力轻高、淋巴细胞为主、蛋白轻度升高、糖氯化物正常。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2000","_shard":"qk-yiliao-03"}]);